quests[2965] = { id = 2965, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Portents of Uldum", description = "Ah, {name}, it is fortuitous that you have come to me again.  Your revelations at the Uldaman dig site have certainly given us sages much discuss.  I was doing just that with one of the druids, Nara Wildmane, when it dawned on me that her past adventuring experiences may have some great importance as to the next step we need to take.\n\nI would like for you to speak with her concerning her travels to the Valley of the Watchers in the Tanaris desert.  She waits for you on the Elder Rise.", completion = "There is a place deep in the Tanaris desert called the Valley of the Watchers.  The discs that you recovered... their translated glyphs make mention of a place called Uldum.  Most think this place to be a myth.\n\nI know this to be false; Uldum exists.  I've been there.  Well... outside, at any rate.\n\nThe crux is this, {name}: we think there is a connection between the discs and Uldum, and we want you to go there.", objectives = "Speak with Nara Wildmane on the Elder Rise in Thunder Bluff.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2966] = { id = 2966, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeing What Happens", description = "Sage Truthseeker and I would like you to take the miniature discs you found to the sealed gates of Uldum.  We... we aren't sure what will happen when you do this.\n\nThis sounds risky, sure, we acknowledge that.  It might, however, do nothing.  You might need to use the discs on something.  Perhaps the doors unlock when you have the discs in your possession.  Be open to try anything, and be ready for anything to happen.\n\nLearn what you can, then return to me. We will have much to discuss.", progress = "This familiar looking pedestal sticks out of the hot sand.  Perhaps there is something to its presence here...", completion = "As you touch the pedestal, the miniature discs from Uldaman hum and glow in your backpack.  A familiar feeling tingle washes over your hands, as the image of another Stone Watcher springs to life in front of the gates of Uldum.\n\n\"Salutations.  I am a guardian of entry.  The discs that have been used for access are missing the correct entry discs, the Plates of Uldum.  Please incorporate these plates with the disc structure and repeat your access sequencing.  Thank you.\"", objectives = "Bring the miniature platinum discs to the gates of Uldum in Tanaris and look for clues as to the connection between the two.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2967] = { id = 2967, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Thunder Bluff", description = "You access the pedestal again; the platinum discs suddenly appear once more in your backpack.\n\nWith the knowledge of the stone watcher learned and the discs returned to your possession, the time has come to return to Thunder Bluff and inform the Nara Wildmane of your discovery.", progress = "Welcome back {name}.  Were you able to use the discs to your advantage, or was it for naught?", completion = "You were missing some discs?  Interestingly enough, it seems that the discs of Norgannon are only parts of the complete set - like keys on a key ring, if you will.\n\nIf we can find the Plates of Uldum, then we could actually access the Uldum complex itself.  I don't know whether to be excited by that prospect, or be terrified.\n\nWe may need to risk everything to ensure that those secrets the earth keeps which would destroy us all remain just that - secrets.", objectives = "Speak with Nara Wildmane in Thunder Bluff.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2968] = { id = 2968, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Future Task", description = "Well {name}... we seem to be at an unfortunate impasse.  We know what we need - the Plates of Uldum - but we have no idea where they might be.  We will research this, and then devise a solid plan of attack.  I have a couple ideas where to start looking; I have high hopes that soon, we'll be asking you to rejoin our efforts to discover the truth.\n\nSage Truthseeker needs to be informed on this, {name}; no doubt, he also wants to thank you personally for once again heeding the call.", completion = "We're all in agreement then - the best course of action is to wait until we can narrow down the areas where these plates might lie hidden.  You've brought us this far {name}, and I hope you will be the one to head back in to the field to confront the secrets of Uldum.\n\nAllow me to give you this honorarium in the meantime; this should cover any expenses you've encountered in assisting us, and a little something extra.  Be sure to check back with us soon... Uldum beckons us all, young one.", objectives = "Speak with Sage Truthseeker in Thunder Bluff.Well {name}... we seem to be at an unfortunate impasse. We know what we need - the Plates of Uldum - but we have no idea where they might be. We will research this, and then devise a solid plan of attack. I have a couple ideas where to start looking; I have high hopes that soon, we'll be asking you to rejoin our efforts to discover the truth.\n\nSage Truthseeker needs to be informed on this, {name}; no doubt, he also wants to thank you personally for once again heeding the call.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2969] = { id = 2969, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freedom for All Creatures", description = "The filthy Grimtotem clan are capturing faerie dragons, {name}. Jer'kai and I have no idea what they plan on doing with them, but they're obviously up to no good.\n\nWe're not powerful enough to fight our way into the camp and free the captured dragons, but perhaps with your help...\n\nIf you're willing, and you have some strong friends, release the creatures from their cage with this key and make sure they escape with their lives. I'll be by your side the entire time. Jer'kai will remain here.", completion = "Thank Elune, {name}! You are a great blessing to us and to the darters you saved. Jer'kai and I would never have been able to help the dragons ourselves--your intervention in the Grimtotem's affairs will be remembered.\n\nSpeak to Jer'kai now... I have to prepare for our retribution. Just because the faerie dragons are free, it doesn't mean they will remain so. Jer'kai and I will now go on the offensive.", objectives = "Using the Bamboo Cage Key, free the Sprite Darters from the pen in the Grimtotem camp. At least 6 Sprite Darters and Kindal Moonweaver must survive.\n\nYou have 6 minutes before Kindal decides it is time to retreat and you fail the quest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2970] = { id = 2970, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Doling Justice", description = "As she's already told you, Kindal and I will now take the fight to the Grimtotem. Together, we should still be able to pick off some of the tauren without much threat to ourselves, but we'd love some help if you're willing and able.\n\nYou've seen the camp below us, but there are more to the east. Using your own tactics, deal as much damage to the tauren as you can. We can all meet back here after they've felt the sting of Kindal's arrows and your own weapons.", completion = "Kindal was right about you, {name}--you do have a knack for this. You are a more seasoned adventurer than the both of us, and for that we thank you.\n\nThe Grimtotem clan is much more hostile than most tauren... I wonder if their own kind frowns upon their actions. I wouldn't be surprised. As you are probably aware, many races on Azeroth have ties to less kindly counterparts.\n\nBut that is a discussion for another day.", objectives = "Kill 12 Grimtotem Naturalists, 10 Grimtotem Raiders, and 6 Grimtotem Shamans before returning to Jer'kai Moonweaver in Feralas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2972] = { id = 2972, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Doling Justice", description = "Out here in the wilderness, Kindal and I have meager means to reward your help, but we don't want you to feel unappreciated. Take my signet ring. If you ever find yourself in the boughs of Teldrassil, go to the Temple of the Moon in the heart of Darnassus. There you will find my High Priestess Tyrande Whisperwind. The ring will let her know that we are well and give credit to your story.\n\nWe both thank you, {name}.", progress = "Hello, child. It pleases us to have more powerful adventurers here in the temple. If you have the time, will you share a tale or two with the younger adventurers? I know many of them would benefit from your wisdom.\n\nI'm sorry, look how rude of me. You've come to the Temple seeking our aid, and I impose on you. Please, forgive me. Tell me what the servants of the Light can do for you.", completion = "That's an amazing story, {name}. It pleases us that you've not only helped dragonkind, but also one of our own priestess. Jer'kai was right to send you to me. I will make sure she has her ring returned to her--I have scouts heading the direction of Feralas soon. This will be one more thing for them to investigate while on their mission.\n\nThank you again, and please, make yourself at home while you're here.", objectives = "Take Jer'kai's Signet Ring to High Priestess Tyrande Whisperwind in Darnassus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2973] = { id = 2973, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Cloak's Sheen", description = "Well met, {class}. I've traveled with my companions down to the Feralas on a mission for our Orgrimmar masters.\n\nMy life-mate Korrin finds great pleasure in new clothing, so I aim to make her a new cloak adorned with the gossamer wings of faerie dragons. Would you be able to help me? Sprite darters with gorgeous wings I want are west of Camp Mojache.", progress = "The sprite darters can be dangerous critters when provoked. Be careful when dealing with them, {class}. And be even more careful of any night elves in the area. The pestering fools tend to hold up in the forests also.\n\nWhen you've gotten enough of the wings, let me know, I'll be sure to reward you well!", completion = "Wonderful, {class}! These will do nicely. There are enough here to make a cloak for Korrin, and possibly even more! Thank you.\n\nI hope the trip wasn't too dangerous? The area of Feralas is not known for being forgiving, but you've obviously done well enough.\n\nThank you again, {class}.", objectives = "Bring 10 Iridescent Sprite Darter Wings to Krueg Skullsplitter in Camp Mojache.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2974] = { id = 2974, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Grim Discovery", description = "What!? You came across tauren in the area? You're joking! What did they look like!?\n\nThe Grimtotem clan! You found some of them? Belgrom, one of our masters, has an interest in their kind... he's even put a bounty on them.\n\nYou have to go back, {class}. Go back and bring me their horns... piles of them if you can. The Grimtotem are not to be trifled with or underestimated. Go back and slay them; let the rivers in Feralas run red with their dark blood.", progress = "Take my words seriously, {class}, the Grimtotem clan is evil. If you've found their whereabouts, then it's up to you to return and strike the first blow against their clan... before they can come into our own lands and raze our own villages, or pilfer our lands.", completion = "These are good horns, {class}. Well done. I'll take these from you and be sure to tell Belgrom as soon as we return to Orgrimmar. You've helped me twice now, and for that, you have my mark. Perhaps in the future I can help you! Good luck to you.", objectives = "Bring 20 Grimtotem Horns to Krueg Skullsplitter in Camp Mojache.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2975] = { id = 2975, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ogres of Feralas", description = "The effects of the Gordunni Ogre tribe can hardly go unnoticed in this area. Look around, {name}; their very presence scars this land. We must push them back before they expand even further into Feralas.\n\nFollow the river north, and you will find their outpost. Decrease their numbers, {name}. We must show them that their kind is not wanted here.", completion = "Excellent, {name}. In time, the land will heal. We must not give up.", objectives = "Rok Orhan in Camp Mojache wants you to kill 10 Gordunni Ogres, 10 Gordunni Ogre-Magi, and 5 Gordunni Brutes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2976] = { id = 2976, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Grim Discovery", description = "What?!\n\nAh, so I did mention a bounty, didn't I? Well, that'll teach me to open my mouth, won't it?\n\nYou did the work, so I suppose it is only right you reap the greatest reward from it. Take the horns, I'll have them put in a crate for you. Find Belgrom Rockmaul in the Valley of Honor, he'll want to know what you saw and he'll reward you for your hard work.\n\nBe well, {class}, and thank you again for everything you've done.", progress = "Be quick, {class}, I have much to complete today.", completion = "The Grimtotem!? This is interesting. You say you came across them while hunting in Feralas? Truly?\n\nMy peers will want to hear your news, {class}. Tell me more and I'll count out your coin while you do so.\n\nAnd before you go, know that I give you thanks for the information you've passed on to me this day.", objectives = "Bring the Crate of Grimtotem Horns to Belgrom Rockmaul in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2977] = { id = 2977, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Ironforge", description = "You access the pedestal again; the platinum discs suddenly appear once more in your backpack.\n\nWith the knowledge of the stone watcher learned and the discs returned to your possession, the time has come to return to Ironforge and inform the Explorers' League of your discovery.", progress = "Welcome back {name}.  Were you able to use the discs to your advantage, or did it end up being a wild goose chase?", completion = "You were missing some discs?  Interestingly enough, it seems that the discs of Norgannon are only parts of the complete set - like keys on a key ring, if you will.\n\nIf we can find the Plates of Uldum, then we could actually access the Uldum complex itself!  Imagine actually exploring the place where the Creators worked without having to bring a huge shovel!\n\nNot that there's anything wrong with shovels... or digging...", objectives = "Speak with Historian Karnik in Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2978] = { id = 2978, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gordunni Scroll", description = "Picking up the soiled scroll, you notice that it seems to be depicting some sort of meeting or ceremony. Rok Orhan would be interested in this scroll, and what it might mean to the Gordunni.", progress = "What is this?", completion = "This scroll... You found this in the Gordunni Outpost?", objectives = "Bring the Gordunni Scroll to Rok Orhan in Camp Mojache.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2979] = { id = 2979, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Ceremony", description = "These seem to be plans for some sort of dark ceremony, {name}. From what I can make out, this ritual is conducted by the Gordunni mage-lords.\n\nFind one of these mage-lords, and from him, gather an orb.\n\nThe orb of a mage contains great power, and will help us discover more about this ceremony and the magic that the Gordunni wield.", progress = "We must discover more about why the Gordunni are here, {name}.", completion = "This orb will provide us with more information about the Gordunni... which we will then use in planning their downfall, {name}.", objectives = "Rok Orhan in Camp Mojache wants you to find a Gordunni Orb.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2980] = { id = 2980, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ogres of Feralas", description = "Now that you have proven that you are a true fighter, I trust that you possess the courage to continue with the task at hand.\n\nTravel to the High Wilderness, southwest of here. There lie some abandoned and destroyed structures, on land that once belonged to the night elves. Look for these ruins, and when you see the withered trees and desecrated terrain, you will find the Gordunni. Push them back.\n\nThese ogres are much stronger than the ones you faced previously, {name}. Be aware.", completion = "You have proven yourself to be a trustworthy and dependable ally, {name}.", objectives = "Rok Orhan in Camp Mojache wants you to kill 10 Gordunni Shaman, 10 Gordunni Warlocks, and 5 Gordunni Maulers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2981] = { id = 2981, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Threat in Feralas", description = "Feralas is an ideal location for an accomplished {class} to prove <himself/herself>. A tribe of ogres called the Gordunni are the dominant military force there, and their numbers are growing. They must be stopped before they threaten our presence in Feralas.\n\nA warrior I know of named Rok Orhan resides at Camp Mojache in Feralas; go to her. She will tell you more of the situation when you arrive.", completion = "So, Belgrom sent you. You are just in time, {race}.\n\nLet me explain the situation, and then you can decide if you are up to the challenge... But if Belgrom sent you, I am sure your courage is unquestionable.", objectives = "Belgrom Rockmaul wants you to speak with Rok Orhan in Camp Mojache.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2982] = { id = 2982, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The High Wilderness", description = "Although it is dangerous, Troyas and I have been investigating the ruins that cover the forests of Feralas.\n\nLately, though, Troyas has been going on his own to the High Wilderness, and I really worry about him. The Gordunni Ogres have taken over that area, and they don't take kindly to anyone that enters their territory.\n\nI was hoping you might be willing to travel to the ruins to the southeast and clear out some of the ogres. Make it a little safer for my Troyas, and I will be extremely grateful.", completion = "I am very grateful you were able to do this for me.\n\nNow, please, don't mention a word to Troyas about this...", objectives = "Angelas Moonbreeze wants you to kill 8 Gordunni Warlocks, 8 Gordunni Shaman, and 8 Gordunni Brutes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2983] = { id = 2983, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Fire", description = "It's been some time since you were tested last, {name}. You've been patient thus far in your studies, but it's time for you to learn about greater powers... it's time you learn real power. The element of fire is yours if you're prepared to pay for it.\n\nSeek out Kranal Fiss in the Barrens. He lives in a small dwelling north of the Crossroads, but be mindful, if you've reached the blasted night elf lands, you've gone way too far.", sourceObjective = "Find Kranal Fiss in the Barrens.", sourceObjectiveStatus = "unverified-source-field" }
quests[2984] = { id = 2984, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Fire", description = "Long has it been since you were last tested, {name}. You have shown patience thus far in your studies, but the time has come for you to learn more. The time has come for you to learn about destruction... and chaos. The element of fire is yours for the understanding, if you're prepared to pay for it.\n\nSeek out Kranal Fiss in the Barrens. He lives in a small dwelling north of the Crossroads, but be mindful, if you've reached the night elf lands, you've gone too far.", completion = "Hmmm, Narm sent you to me, did he?\n\nWell then, Narm could always be trusted, so that must mean you're ready to take part of the next sapta--the sapta of fire.\n\nI see it in your eyes already, the burning, the desire. You've tasted power, and now you're ready for more of it. Patience, {name}. Remember what earth taught you. Power and destruction will come easily, but you must still know when to stay your hand.", objectives = "Find Kranal Fiss in the Barrens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2985] = { id = 2985, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Water", description = "You look ready for your next test, {name}. You've been patient in your studies, but the time has come for you to learn more. The time has come for you to learn about the purity of water.\n\nSeek out Islen Waterseer in the Barrens. She is along the eastern coast, south of the Southfury River and Ratchet. You will find her there at her fishing hut. Good luck to you, {name}.", sourceObjective = "Find Islen Waterseer in the Barrens.", sourceObjectiveStatus = "unverified-source-field" }
quests[2986] = { id = 2986, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Water", description = "Long has it been since you were last tested, {name}. You have shown patience thus far in your studies, but the time has come for you to learn more. The time has come for you to learn about the purity of water.\n\nSeek out Islen Waterseer in the Barrens. She is along the eastern coast, south of the Southfury River and Ratchet. You will find her there at her fishing hut. Good luck to you, {name}.", completion = "The wind approaches you quickly from the horizon; the earth is steady beneath your feet; and your spirit is already warmed by fire--I would say it is time for you to learn about the purity of water.\n\nYour path has led you this far, and your spirit will give you the strength to carry on even further. But the first step is yours to take.", objectives = "Find Islen Waterseer in the Barrens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2987] = { id = 2987, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gordunni Cobalt", description = "I just arrived here in Feralas, and I've heard that the Gordunni Ogres that inhabit the wilds here have some interesting minerals. Who knows what they are up to, but they sure are protective of that stuff! They don't leave it just lying around; no, they bury it to protect folks like me from getting their hands on it.\n\nIf you'd be willing, I'll give you my shovel. Go to the Gordunni Outpost north of here and dig me up some Gordunni cobalt. Look for the blue glow, then start digging!", progress = "Get on up there and start digging!\n\nI've got places to go and people to see -- time is money!", completion = "Perfect! I will take these along as I continue my travels, {name}. I'm sure I can find someone that will pay a pretty penny for this cobalt.\n\nHere, take this for your trouble.", objectives = "Orwin Gizzmick in Camp Mojache wants 12 samples of Gordunni Cobalt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2988] = { id = 2988, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Witherbark Cages", description = "The son of our mightiest gryphon is gone! Swiftwing's heir, Sharpbeak, was lost while hunting with his parents a few days ago, and we believe it was the trolls who took him.\n\nYou must aid us!  Search the cages in the two Witherbark troll villages to see if Sharpbeak is there.", completion = "Sharpbeak wasn't at the villages?  Hm... this is grim news.  That gryphon is destined to lead the next generation of gryphons.  If he is lost then the strength and spirit of our fleet will suffer immensely.", objectives = "Check the cages at the two Witherbark villages, then return to Gryphon  Master Talonaxe.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2989] = { id = 2989, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Altar of Zul", description = "Sharpbeak was not with the Witherbark trolls.  Perhaps the Vilebranch trolls took him.  Go to the Altar of Zul on the western edge of Vilebranch territory and search for the gryphon child.", completion = "Sharpbeak wasn't there?  That is bad news, but it is good news too...\n\nIt is good that he was not at the Altar of Zul for the Vilebranch trolls are known for performing sacrifices.\n\nI thank you for all of your aid, but I'm afraid I have an even greater task ahead.", objectives = "Check the top of the Altar of Zul, then return to Gryphon Master Talonaxe.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2990] = { id = 2990, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thadius Grimshade", description = "Take this feather to Thadius Grimshade, the diviner.  He left Aerie Peak years ago to pursue darker knowledge, but in his heart he is still a Wildhammer!\n\nAnd perhaps his talents can help us find Sharpbeak.\n\nThis feather was taken from the nest where the gryphon child sleeps.  If you give it to Thadius then, with luck, he can use his divining magics to find Sharpbeak.\n\nGood luck, {name}.  You will find Thadius in the Blasted Lands, in the mage tower of Nethergarde Keep.", progress = "{name}, you come bearing a gift?", completion = "Ah, yes.  This feather belongs to a fine gryphon.  One destined for great things... if he can survive into adulthood undamaged.\n\nYou wish to find him?  Then listen close, brave {class}...", objectives = "Bring Sharpbeak's Feather to Thadius Grimshade in the Blasted Lands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2991] = { id = 2991, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nekrum's Medallion", description = "I'll find out where your gryphon is, but first you have to do something for me.  There's a troll in Zul'Farrak, Nekrum Gutchewer, who possesses a medallion I would very much like to study.  Bring me that Medallion and I'll use my powers to find Sharpbeak.\n\nZul'Farrak is across the ocean to the west, in the desert of Tanaris.", progress = "Do you have Nekrum's Medallion, {name}?  There are powers hidden within it that I am eager to discover.", completion = "Ah, the medallion of Nekrum.  It is rumored to have given the troll an unnatural long life, but at a cost.  I hope to discover a way to reap the medallion's power while avoiding its... unpleasant side effects.\n\nYou have done me a service, {name}.  I shall now uphold my end of our bargain.", objectives = "Bring Nekrum's Medallion to Thadius Grimshade in the Blasted Lands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2992] = { id = 2992, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Divination", description = "Give me room while I perform a ritual of divination.  I will find the connection between the feather you brought me and its owner, and follow that connection to Sharpbeak himself.\n\nThat is... I will if all goes according to plan.  If it does not, then... you better close your eyes.", completion = "The ritual was a success.  I have seen Sharpbeak and can tell you how to find him.", objectives = "Wait until Grimshade performs the ritual of divination.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2993] = { id = 2993, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the Hinterlands", description = "Sharpbeak is held in a cage, high on a cliff at the top of Jintha'Alor in the Hinterlands.  The key to this cage is possessed by the high priestess of the Vilebranch trolls, Vile Priestess Hexx.\n\nThere.  I have done my part.  I bid you fortune on your quest, {name}.", completion = "You've spoken with Grimshade?  What did he say?\n\n...What?  The Vilebranch trolls have Sharpbeak?  That's unbearable!  We must organize a force to get him back!", objectives = "Speak with Gryphon Master Talonaxe.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2994] = { id = 2994, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saving Sharpbeak", description = "We must save Sharpbeak!\n\nFight your way to the top of Jintha'Alor in the heart of Vilebranch territory, gain the key to Sharpbeak's cage from the vile Priestess Hexx, and then find and save Sharpbeak!", completion = "Swiftwind and Keenclaw returned with their child moments ago, and are fussing over him like new parents.  Seeing them together again is enough to give even this old dwarf mist in the eyes...\n\nWe cannot repay you enough for what you have done, {name}.  The gryphons of Aerie peak, and their riders, will sing your name for a long, long time.", objectives = "Fight to the top of Jintha'Alor, kill Vile Priestess Hexx for the key to Sharpbeak's cage, and save Sharpbeak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2995] = { id = 2995, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lines of Communication", description = "The Quel'Danil Lodge is a center of communication for the high elves of the Hinterlands. Their ambassadors are working to establish relationships with other races, with whom they share their knowledge of the Witherbark trolls that inhabit the area in the southern Hinterlands. All of the documents regarding the communications are kept at the lodge.\n\nWe don't need the Highvale building alliances with others, {name}.\n\nDestroy the Highvale documents.  We need to burn their lines of communication... literally.", completion = "Perfect, {name}. While the Highvale work to recover their lost information, we will be able to seal off the lines even further...", objectives = "Burn the Highvale Records, Highvale Report, and Highvale Notes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[2996] = { id = 2996, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeking Strahad", description = "I have taught you skills in the past, but the time has come for another to teach you. He is in Ratchet, and his name is Strahad. He is human, but do not let that fool you into thinking he is weak. He is powerful even though he may be small. He can teach you about more powerful summonings--I feel you are ready. Go to him now. He is in Ratchet... above the port town next to his tower.", sourceObjective = "Speak to Strahad Farsan in Ratchet.", sourceObjectiveStatus = "unverified-source-field" }
quests[2997] = { id = 2997, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tome of Divinity", description = "Hello, {name}. I know you're busy helping out the people of Dun Morogh, but when you have the time, you should make your way up to Ironforge to speak to one of our most respected ilk: Tiza Battleforge. She's the one the younger paladins go to when it's time they learn more about the Light and what's expected of ya.\n\nYou can find her upstairs in the Hall of Mysteries. If you've never been there, it's in the Mystic Ward. Good luck to ya, {name}.", sourceObjective = "Speak to Tiza Battleforge in Ironforge.", sourceObjectiveStatus = "unverified-source-field" }
quests[2998] = { id = 2998, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tome of Divinity", description = "Greetings, <brother/sister>. Duthorian Rall, one of our most influential paladins, was speaking about you recently. I overheard him talking about how it was time you be put to the test some... along with some very complimentary things about how well you've performed thus far.\n\nIf I were you, I'd head to Stormwind and speak to him when you have time. I'm sure he's in the Cathedral of Light--that's where he spends most of his time.", sourceObjective = "Speak to Duthorian Rall in Stormwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[2999] = { id = 2999, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tome of Divinity", description = "Hello, {name}. I know you're busy helping out the people of Dun Morogh, but when you have the time, you should go upstairs and speak to one of our most respected ilk: Tiza Battleforge. She's the one the younger paladins go to when it's time they learn more about the Light and what's expected of ya.", sourceObjective = "Speak to Tiza Battleforge in Ironforge", sourceObjectiveStatus = "unverified-source-field" }
quests[3000] = { id = 3000, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tome of Divinity", description = "Hello, {name}. I know you're busy helping out the people of Azeroth, but when you have the time, you should return to Ironforge and speak to one of the most respected paladins of your home: Tiza Battleforge. She's the one the younger dwarven paladins go to when it is time they learn more about the Light and what's expected of all of us.\n\nYou can find her upstairs in the Hall of Mysteries which is located in the Mystic Ward.", sourceObjective = "Speak to Tiza Battleforge in Ironforge.", sourceObjectiveStatus = "unverified-source-field" }
quests[3001] = { id = 3001, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeking Strahad", description = "I have taught you skills in the past, but the time has come for another to teach you. He is in Ratchet, and his name is Strahad. He is human, but do not let that fool you into thinking he is weak, nor is he your enemy... at least for now. He is powerful and should be respected. He can teach you about greater summonings, summonings I feel you are prepared for. Go to him now.\n\nYou can find him in Ratchet... above the port town next to the tower there.", sourceObjective = "Find Strahad Farsan in Ratchet.", sourceObjectiveStatus = "unverified-source-field" }
quests[3002] = { id = 3002, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gordunni Orb", description = "Although I know my enemy well, I am a warrior, {name}. I cannot begin to tell you what this orb is capable of.\n\nI know of a mage in Orgrimmar that will be able to tell us more about the orb. Take it to him.", progress = "What have you brought me, {race}?", completion = "Fascinating, {name}...\n\nThis orb is very powerful, but also very dangerous.", objectives = "Bring the Gordunni Orb to Uthel'nay in the Darkbriar Lodge in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3022] = { id = 3022, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handle With Care", description = "{name}, I can see you yearn to be dedicated to my worthwhile cause. Yes, of course, you can do something for me!\n\nTake this crate of eggs to Erelas Ambersky. He is a druid that cares for these eggs, helping them to hatch and then training the young hippogryphs. You will find him in Teldrassil, in a small village to the south called Rut'theran.", progress = "Another shipment from Curgle, I assume?", completion = "Thank you for your help, {name}. The hippogryph population simply wouldn't flourish if it weren't for us. Ah, but I am sure you understand all too well, having traveled to Feralas yourself, and seen the devastation of the Gordunni there.\n\nWell, as you can see, I am hard at work here, so you'd best be on your way.\n\nThanks again, {name}.", objectives = "Bring the Carefully-packed Crate to Erelas Ambersky in Rut'theran Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3042] = { id = 3042, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Troll Temper", description = "The Sandfury trolls of Zul'Farrak make a tempering agent from sandstones, and I can use that to temper the goods I craft.  It is highly prized by connoisseurs, so if you bring me a good supply of the temper, then I'll reward you well.\n\nZul'Farrak is northwest of Gadgetzan.  Good luck.", progress = "Did you bring me the temper, {name}?", completion = "Ah, this is very nice temper indeed!  And so much of it!  I'll be at work for days before I use it all!\n\nThank you, {name}.  Please, take this as payment.", objectives = "Bring 20 Vials of Troll Temper to Trenton Lighthammer in Gadgetzan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3062] = { id = 3062, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Heart", description = "Edana Hatetalon is the queen of the Northspring harpies that reside in the ruins to the west. She is pure evil; I have heard that her heart is one of crystal. She is void of any emotion aside from the hate she feels towards all others. You must face Edana and bring me back her dark heart.\n\nI have heard of a horn that harpies carry -- blowing it by the Hatetalon stones, in the northern part of the ruins, will summon the queen.\n\nImagine her surprise when it is not her kin calling her, but her death.", progress = "The hate that Edana spreads across the land must be stopped.", completion = "Now I know that Edana is truly dead. This heart; I will keep it in memory of what did here for me, {name}. Thank you.", objectives = "Talo Thornhoof in Camp Mojache wants Edana Hatetalon's Dark Heart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3063] = { id = 3063, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vengeance on the Northspring", description = "In my day, I was a seasoned hunter. There wasn't any creature around that I feared. Until...\n\nI was out in the forest, sharpening my blade after a tough battle, when I was ambushed. Harpies surrounded me, and I barely managed to drag myself to safety.\n\nEven now, I can still hear their cries echoing...\n\nI was never the same after that. But the hate boils inside of me -- I must get even, after all these years.\n\nThe Northspring harpies can be found to the west of here. {name}, get my revenge.", completion = "Thank you, {name}. You have put an old tauren's mind at peace.", objectives = "Talo Thornhoof wants you to kill 4 Northspring Harpies, 4 Northspring Roguefeathers, 4 Northspring Windcallers, and 4 Northspring Slayers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3065] = { id = 3065, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Simple Tablet", description = "Ah, while you were gone a parchment came for you, {name}.\n\nRead it when you have time. If I'm not mistaken, it came from the warrior trainer Frang. He would have words with you when you're ready. You'll find him outside the Den, taking cover in the shade.", progress = "Another {race} to bolster the ranks. Good enough for me.\n\nYou'll probably have a hard time hefting a good weapon like an axe, but a spear's just as good as anything else.\n\nWelcome to the Valley of Trials.", completion = "You'll find this place fitting as you continue to train in the {class} ways. If you have any questions, feel free to ask anyone around, and when you feel you're ready, come back to me for training. I've mastered as much as any {class} here in the Valley and can pass that knowledge on to you... for a price.", objectives = "Read the Simple Tablet and speak to Frang in the Valley of Trials.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3082] = { id = 3082, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Etched Tablet", description = "Ah, while you were gone a tablet came for you, {name}.\n\nRead it when you have time. If I'm not mistaken, it came from the hunter trainer Jen'shan. She would have words with you when you're ready.", objectives = "Speak to Jen'shan in the Valley of Trials.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3083] = { id = 3083, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Encrypted Tablet", description = "Ah, while you were gone a tablet came for you, {name}.\n\nRead it when you have time. If I'm not mistaken, it came from the rogue trainer Rwag. He would have words with you when you're ready.", progress = "Welcome to the Valley of Trials, {name}. You wouldn't be here if you hadn't gotten my tablet, so I will get to the point.\n\nI am Rwag and I am responsible for training the rogues, thieves, and cutpurses here in the Valley. I'm the one the Hand will turn to if you're not ready for what's to come. But don't worry, the Hand won't be controlling everything you do, but it would be wise to work with them if they have need of your talents.", completion = "Until such time comes, you'll be under my tutelage. I will show you the ropes as some folks say. Whenever you feel prepared, come to me and I will see about training you further. Until then, practice your skills and keep them honed to a razor's edge. You'll never know when you'll need even the most insignificant ability.", objectives = "Read the Encrypted Tablet and speak to Rwag in the Valley of Trials.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3084] = { id = 3084, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rune-Inscribed Tablet", description = "Ah, while you were gone a tablet came for you, {name}.\n\nRead it when you have time. If I'm not mistaken, it came from the shaman trainer Shikrik. She would have words with you when you're ready.", progress = "Ah, welcome, {name}. I'm pleased you have arrived. My days have become long and even busy what with so many students to teach, but the coming of one of your ilk brings me a great sense of accomplishment--I remember the days when I was taught by one of your shamans.", completion = "As you probably know, the elements give us our power. Fire, earth, water and air--these are our tools.\n\nOur strength comes from the spirits of our ancestors. We are the leaders of our people. Like Thrall is to the Horde, so shall we be to the villages and towns we visit. They will look to us for wisdom and protection. To be better prepared, you must train often. When you feel you've gained more power, come to me and I shall teach you what I can.", objectives = "Speak to Shikrik in the Valley of Trials.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3085] = { id = 3085, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hallowed Tablet", description = "Ah, while you were gone a tablet came for you, {name}.\n\nRead it when you have time. If I'm not mistaken, it came from the priest trainer Ken'jai. He would have words with you when you're ready.", progress = "So ya made it... good good! Da spirits tol' me you be comin' to see Ken'jai soon enough. Let me be one o' da first to welcome ya to da Valley of Trials. Dis place not be your home fer long, but while it is, why dontcha make da best o' it.", completion = "As ya test yeself, ya'll find ya have better an' better control o'er da spirits--ya'll be callin' on dem fer greata an' greata tings...  dat's where ol' Ken'jai come in. You come talk to ole Ken'jai when ya feel yer ready. If da spirits agree, den we see 'bout teachin' ya more powerful abilities... but only if da spirits agree.\n\nGo now, talk to da rest of da Valley's people. Speak to me again later.", objectives = "Read the Hallowed Tablet and speak to Ken'jai outside the Den in the Valley of Trials.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3086] = { id = 3086, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glyphic Tablet", description = "Ah, while you were gone a tablet came for you, {name}.\n\nRead it when you have time. If I'm not mistaken, it came from the mage trainer Mai'ah. She would have words with you when you're ready.", progress = "Ya look to please Mai'ah already, {name}. Dat be good. You give Mai'ah respect, and Mai'ah maybe give you respect back. But enough o' dat, you be here to learn 'bout magic, not hear Mai'ah talk.\n\nThere be only one ting Mai'ah can no teach you 'bout magic, {name}, and dat's how to stop da corruptin'.", completion = "You be among da most powerful beings on da planet, {name}... there no arguin' dat. And everyone know it... know it good, too!\n\nBut ya must be weary! 'cause it not orc, or elf, or dwarf dat you should be scared of... it be da tings you can'na see. Magic be powerful. Make you do tings you may not want to do. Make ya tink you more powerful then you really be. Be patient. Be smart.\n\nWhen ya tink you be ready for trainin', come back to Mai'ah. She teach you what you ready to learn, no problem.", objectives = "Read the Glyphic Tablet and speak with Mai'ah near the entrance to the Den in the Valley of Trials.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3087] = { id = 3087, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Etched Parchment", description = "Ah, while you were gone a parchment came for you, {name}.\n\nRead it when you have time. If I'm not mistaken, it came from the hunter trainer Karranisha. He would have words with you when you're ready.", progress = "Many come to me with the desire to be a {class}, but few follow through.  It's easy to underestimate our job.  Being a {class} is far more than just aiming and shooting.", completion = "As a {class}, my skill rivals the arcane powers of the mages, the martial prowess of the warriors, or even the blessed acts of our beloved shaman.  To be a {class} requires focus and dedication.  Let us continue.", objectives = "Read the Etched Parchment and speak to Karranisha in the Valley of Trials.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3088] = { id = 3088, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Encrypted Parchment", description = "Ah, while you were gone a parchment came for you, {name}.\n\nRead it when you have time. If I'm not mistaken, it came from the rogue trainer Rwag. He would have words with you when you're ready.", progress = "Shhh, not so loud.  The enemy has ears everywhere.", completion = "Now that you know where I'm holding up, I should let you know: the Shattered Hand's asked me to look out for you. They want me to train you and keep you informed of anything they might need. Even if you're not interested in helping them yet--which you'd be a fool not to be--I'll do what I can to train you... for a small fee.", objectives = "Read the Encrypted Parchment and speak to Rwag in the Valley of Trials.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3089] = { id = 3089, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rune-Inscribed Parchment", description = "Ah, while you were gone a parchment came for you, {name}.\n\nRead it when you have time. If I'm not mistaken, it came from the shaman trainer Shikrik. She would have words with you when you're ready.", progress = "So, you've arrived. I was beginning to wonder when you would show yourself. I sent the parchment some time ago--I wasn't sure if it had arrived.\n\nBut enough chatter... you're here because you have been chosen: chosen to lead the spiritual lives of our people.", completion = "You will be the conduit in which our ancestors communicate.  You will have the power of the elements at your beck and call.  Sundering your enemies will be child's play; healing your allies as easy as breathing.\n\nBut not yet.  First, you train.", objectives = "Read the Rune-Inscribed Parchment and speak to Shikrik in the Valley of Trials.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3090] = { id = 3090, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tainted Parchment", description = "Ah, while you were gone a parchment came for you, {name}.\n\nI usually avoid dealing with warlocks if I can help it, but I think you should read it when you have time. If I'm not mistaken, it came from your newly-appointed trainer Nartok. He would have words with you when you're ready.", progress = "Finally, you've arrived... and discretely also. Good.\n\nOur world is full of fools, {name}. Even the mighty Thrall has greater flaws than most can see. He turns his back on the power needed to make this land ours completely! We're not the same people who were manipulated and used by creatures from the Nether. We are our own people. We are proud... and we are strong.", completion = "And now you've joined our ranks also. Don't misunderstand, {name}. Just because you have access to power that many will be jealous of, it does not mean you will be accepted easily.  Hellscream allows our kind into Orgrimmar because we are still his fellow kin--he cannot turn his back on us, or we would become as pathetic as the humans who enslaved him. My point is: be careful. You can be powerful, but if you are foolish, then you are as good as dead.", objectives = "Read the Tainted Parchment and speak to Nartok in the Valley of Trials.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3091] = { id = 3091, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Simple Note", description = "Just a moment ago a messenger was looking for you, {name}. I believe she was sent by the warrior trainer Harutt. If this note is from Harutt, I wouldn't take long in reading its contents.", progress = "Ah, at last, you've arrived, {class}. I did not lie in my note, {name}. We are a special breed also, not unlike the druids or shamans of our tribe. You are just as important. We are the ones called upon to defend our borders, to hunt the centaur, and to go to war.", completion = "Each of us plays a role in our tribe. Each of us must also go through all the same rites. Do not ever let your pride tell you otherwise.\n\nI remain here to train new warriors that seek the glory of battle and who follow the ways of our oldest ancestors. When you feel ready, come back to me and I will do what I can to train you further. Go with the tribe's blessing, {name}.", objectives = "Read the Simple Note and speak to Harutt Thunderhorn in Camp Narache.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3092] = { id = 3092, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Etched Note", description = "Just a moment ago a messenger was looking for you, {name}. I believe she was sent by the hunter trainer Lanka. If this note is from Lanka, I wouldn't take long in reading its contents.", progress = "Welcome to Camp Narache, {name}. I hear good things about you. Your bloodline is strong, and many of the elders consider you skilled already. But that we will test.\n\nThe plains of Mulgore will be your home for sometime--you should do your best to learn it very well. One day you will travel to unfamiliar lands to master greater skills. You must be ready.", completion = "And it is my job to make sure you are prepared by teaching you the basics of our profession--how to tame your pet, how to fire your rifle, and many other skills that will become necessary.\n\nHunters are a strong part of our tradition and history, {name}. You would do well to remember how important you are to the tribe. You will be respected and revered if you serve our people well.", objectives = "Read the Etched Note and speak to Lanka Farshot in Camp Narache.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3093] = { id = 3093, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rune-Inscribed Note", description = "Just a moment ago a messenger was looking for you, {name}. I believe she was sent by the shaman trainer Meela. If this note is from Meela, I wouldn't take long in reading its contents.", progress = "As quickly as water falls from the sky, here you are before me. I am pleased by your haste. It means you realize both the importance of our meeting and you being here. I am no leader, but I do understand the elements, and I can speak to the spirits of our people. I will teach you to do the same.", completion = "We will meet many times in the days to come. Each time you will hopefully leave my company a little more powerful... a little more prepared. Like the Eternal Flame, your spirit will burn bright and hot.\n\nGo now, {name}. Go and test yourself. I will be here for you when you need.", objectives = "Read the Rune-Inscribed Note and speak to Meela Dawnstrider in Camp Narache.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3094] = { id = 3094, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verdant Note", description = "Just a moment ago a messenger was looking for you, {name}. I believe she was sent by the druid trainer Gart. If this note is from Gart, I wouldn't take long in reading its contents.", progress = "You have arrived. This is good. Our ancestors' spirits have become restless throughout Mulgore and beyond, but I cannot tell why. It will forever be your duty to learn to listen to nature's spirits, and act as their avatar. Be mindful of that.", completion = "Though we share a common bond, do not expect much welcome from the night elves. Their pride still limits their sight, but that is none of our concern. The teachings of the Earthmother are all you must concern yourself with, and I will teach you what I know as you grow in wisdom.\n\nReturn to me often, {name}. You will find that the Earthmother grants incredible abilities to those who are most dedicated.", objectives = "Read the Verdant Note and speak to Gart Mistrunner in Camp Narache.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3095] = { id = 3095, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Simple Scroll", description = "Ah, while you were off dealing with the mindless Scourge, this scroll arrived for you. I would think it's some matter of importance as it seems it bears the seal of the warrior trainer Dannal. I would take some time to read it before heading out again.", progress = "Ah, so you've arrived. Good. I overheard that a few others were able to escape \"death\" and were heading into town. Perhaps that resilience will pay off in the future also.\n\nYou may thank Sylvanas for your freedom... freedom of mind and body. Though you still remain tortured by the plague and its effects, you are now free to come and go as you see fit.", completion = "I will be here to train you as you grow in experience... find me as often as you like. I charge a minimal fee, but you'll find everything I can teach you to be worthwhile.\n\nGo now and test your skill. Many more things will become known to you as you gain experience, some of which I am unable to discuss with you here. Just know that Sylvanas will need warriors with your type of strength in the future. You will be the backbone of our salvation. Do not forget it.", objectives = "Read the Simple Scroll and speak to Dannal Stern in Deathknell.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3096] = { id = 3096, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Encrypted Scroll", description = "Ah, while you were off dealing with the mindless Scourge, this scroll arrived for you. I would think it's some matter of importance as it seems it bears the seal of the rogue trainer David Trias. I would take some time to read it before heading out again.", progress = "So you've made it? Good, we'll have need of more rogues as time goes on. The Shadowstalkers will probably wind up finding you when they think the time's right, so don't go and slip up or do anything you might regret. They need talented agents... not pickpockets and fools.", completion = "I spend most of my time here in the inn keeping an eye out for new faces and just keeping tabs on up-and-coming prospects. Keep your nose clean and I'll do what I can to teach you a few things. Just come back to me whenever you want, and we'll see if you're ready for a new skill or two.", objectives = "Read the Encrypted Scroll and speak to David Trias in Deathknell.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3097] = { id = 3097, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hallowed Scroll", description = "Ah, while you were off dealing with the mindless Scourge, this scroll arrived for you. I would think it's some matter of importance as it seems it bears the seal of the priest trainer Duesten. I would take some time to read it before heading out again.", progress = "Ah, so between fire, plague, rioting, and much worse, one more of the \"faithful\" comes to my door. Well, let me bid you welcome, {class}. And allow me a moment to explain a thing or two before you decide it's time for you to seek whatever drives you forward: the Holy Light no longer concerns you, the spirits of your forefathers are fairy tales, and creatures from the Nether don't want you.\n\nDo you understand me so far?", completion = "There is only one thing you must know: we have survived through will alone. It is faith in ourselves that separates us from others, and with our powers, we will cause great change in all of Azeroth. The weak will come to lean on you. The lepers will call you Lord. And the ignorant will look to you for guidance. It is my duty to make sure you have the necessary tools so when the time comes, you are prepared. As you grow in experience, seek me out. I will teach you greater powers if you are ready.", objectives = "Read the Hallowed Scroll and speak to Dark Cleric Duesten in the church in Deathknell.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3098] = { id = 3098, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glyphic Scroll", description = "Ah, while you were off dealing with the mindless Scourge, this scroll arrived for you. I would think it's some matter of importance as it seems it bears the seal of the mage trainer Isabella. I would take some time to read it before heading out again.", progress = "I knew you would come to me, {name}. Not because you do not have the will to follow your own path, but because we are kindred spirits. We both have felt pain. We have both suffered. And now we want the power to take back what we know is ours: this land, our lives, our destinies. But there is much for you to learn still.", completion = "You must return to me often if you are to become powerful enough to destroy those who would oppose us. The rules of magic still apply to you, {name}. You will still find corruption follows you like hungry wolves in the night. You will find its caress is not unlike an addiction, an old lover still wanting to be by your side. But these things can be staved off. These things will only control you if you allow them to.\n\nGo now, return to me when you've grown more powerful.", objectives = "Read the Glyphic Scroll and speak to Isabella in the church in Deathknell.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3099] = { id = 3099, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tainted Scroll", description = "Ah, while you were off dealing with the mindless Scourge, this scroll arrived for you. I would think it's some matter of importance as it seems it bears the seal of the warlock trainer Maximillion. I would take some time to read it before heading out again.", progress = "I bid you welcome, brother. I knew you would come. It was only a matter of time.\n\nWhat I said interested you, didn't it? I hit a chord... something inside you knew what I claimed was truth. Good.\n\nKnow this though: I am no traitor to Sylvanas. If anything, she would appreciate my claims considering it was her own beliefs that has put the Forsaken in the position it is now.", completion = "I mentioned a slave still being a slave, no matter the master. Do you remember? We both know that it is that type of control--that type of power--that now drives us. We seek to have creatures serve us. We know we are more powerful and deserve more respect than others give us ... and so now we look to take it.\n\nI will be your ally in this struggle--the struggle for our own freedom. Freedom to seek our own allegiances. When you feel ready, return to me and I will teach you all I know.", objectives = "Read the Tainted Scroll and speak to Maximillion in Deathknell.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3100] = { id = 3100, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Simple Letter", description = "I was asked to bring this to your attention as soon as you returned from dealing with the Blackrock spies, {name}. It appears to be a letter sealed with the insignia of Llane, our local warrior trainer. I wouldn't hesitate to read it before you go about any other business here in the Abbey.", progress = "Ah, you got my letter, {name}... good.\n\nThere's been an influx of warriors in Elwynn recently--which is good for Stormwind, but bad for the orcs in the area.", completion = "Get yourself squared away, learn the layout of the land, and come back to me whenever you need training. I'll be here night or day.\n\nThe Knights of the Silver Hand have done well in making this place fairly safe, but as you meet the other citizens, I think you'll find they all have problems they could use some help with--help a {class} can give them. Good luck.", objectives = "Read the Simple Letter and speak to Llane Beshere in Northshire Abbey.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3101] = { id = 3101, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Consecrated Letter", description = "I was asked to bring this to your attention as soon as you returned from dealing with the Blackrock spies, {name}. It appears to be a letter sealed with the insignia of Brother Sammuel, our local paladin trainer. I wouldn't hesitate to read it before you go about any other business here in the Abbey.", progress = "Finally! We meet face to face, brother to brother. I welcome you to Northshire. This will be your home for a short time while you learn the ins and outs of how things are done, but know that Stormwind is not far off, and sooner or later, your path will take you there. But until then, be patient... Knight of the Silver Hand.", completion = "In the meantime, you should know one or two other things. You are a symbol to many here in this land--act accordingly. The Holy Light shines within you, and it will be obvious to both your allies and your enemies.\n\nAlso, as you gain in wisdom and power, you will need to train to learn new abilities. That's where I come in. When you feel you've gained some experience here in Northshire, come back to me and I will teach you what I feel you are ready to learn. Good luck... {class}!", objectives = "Read the Consecrated Letter and speak to Brother Sammuel in Northshire Abbey.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3102] = { id = 3102, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Encrypted Letter", description = "I was asked to bring this to your attention as soon as you returned from dealing with the Blackrock spies, {name}. It appears to be a letter sealed with the insignia of Jorik, one of our local trainers. I wouldn't hesitate to read it before you go about any other business here in the Abbey.", progress = "You made it here in one piece, and it doesn't look like too many people saw you. Good enough for me. I don't like to have much attention drawn to me back here... nice and quiet. I'm sure you can understand.\n\nHave any trouble yet? I'm glad to hear not. That'll change soon enough.", completion = "You're gonna find a number of outfits that covet our skills, {name}. Adventurers, SI:7... heck, even the disorganized rabble wouldn't mind a spy or two inside Stormwind. But you remember this: You're your own man. Don't let nobody bully you into doing something you don't wanna do! Besides, we hold all the cards... at least, we do before the game's done. Know what I mean?\n\nAnyway, just wanted to introduce myself and let you know that I'm here if you need any training. Come by anytime.", objectives = "Read the Encrypted Letter and speak to Jorik Kerridan in the stable behind Northshire Abbey.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3103] = { id = 3103, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hallowed Letter", description = "I was asked to bring this to your attention as soon as you returned from dealing with the Blackrock spies, {name}. It appears to be a letter sealed with the insignia of Priestess Anetta, our local priest trainer. I wouldn't hesitate to read it before you go about any other business here in the Abbey.", progress = "Ah, at last you've come. I knew you would find your way to me. The Holy Light shines upon you, and the path you've chosen. These times are harsh--the Burning Legion still has a presence upon Azeroth, the entirety of Kalimdor seeks new ways to defend itself from its own tribulations, and it is up to you to aid as many as you can.", completion = "As you grow in experience, return to me and I will do what I can to impart my knowledge upon you. Until then, go with compassion in your heart, and let wisdom be your guide. Remember, the world only becomes a better place if you make it so.", objectives = "Read the Hallowed Letter and speak to Priestess Anetta in Northshire Abbey.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3104] = { id = 3104, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glyphic Letter", description = "I was asked to bring this to your attention as soon as you returned from dealing with the Blackrock spies, {name}. It appears to be a letter sealed with the insignia of Khelden, our local mage trainer. I wouldn't hesitate to read it before you go about any other business here in the Abbey.", progress = "Hello, {name}. I am Khelden. Is there something I can do for you?", completion = "Haha, I knew my note would not dissuade you from your path. So, you're prepared then, are you? Prepared to accept your fate? Prepared to challenge the gods and any other forces that stand before you in the pursuit of knowledge and power?\n\nI will not lie, {name}, you will be feared as much as respected. But also know this, I will be here for you when you need training. Simply seek me out as you grow more powerful.", objectives = "Read the Glyphic Letter and speak to Khelden Bremen inside Northshire Abbey.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3105] = { id = 3105, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tainted Letter", description = "I was asked to bring this to your attention as soon as you returned from dealing with the Blackrock spies, {name}. It appears to be a letter sealed with the insignia of Drusilla, one of our local trainers. I wouldn't hesitate to read it before you go about any other business here in the Abbey.", progress = "Ah, so you've arrived, and not a moment too soon, {name}. Some of the guards were over here a moment ago and were giving me curious looks... pathetic mundanes.", completion = "As you grow in power, you will be tempted--you must always remember to control yourself. I will not lie--corruption can come to any practitioner of the arcane; especially one who deals with creatures from the Twisting Nether. Be patient, and be prudent... but do not let that repress your ambition.\n\nAs you grow more powerful, return to me and I will teach you more about our ways.", objectives = "Read the Tainted Letter and speak to Drusilla La Salle next to Northshire Abbey.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3106] = { id = 3106, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Simple Rune", description = "{name}, this rune was given to me to pass on to ye. Take some time to read it when ye have a chance. I'm thinkin' it came from the warrior trainer Thran. Take a gander at it and go find him inside Anvilmar.", progress = "Blast it's cold today, ain't it? It's like the snow never goes away, {name}.", completion = "If you look around, you'll see a few interesting things: dwarves using magic in a fight instead of a rifle. Some of us have taken to worshipping the Holy Light like some of the humans, and, last but not least, troggs. You'll learn more about them later, but what you need to know now is that I'm here to help you.", objectives = "Read the Simple Rune and speak to Thran Khorman in Coldridge Valley.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3107] = { id = 3107, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Consecrated Rune", description = "{name}, this rune was given to me to pass on to ye. Take some time to read it when ye have a chance. I'm thinkin' it came from the paladin trainer Bromos. Take a gander at it and go find him inside Anvilmar.", progress = "So, you've made it! And not a second too soon. There's much to be done in Coldridge Valley and beyond. I'm gonna need your help as much as you're gonna need mine!\n\nYou're a Knight of the Silver Hand now, be ready to play the part.", completion = "The humans have taught us a great deal about the Holy Light and how important their order is to them... and to protecting all of Azeroth. We have a great respect for how it is steeped in tradition, and how just one figure, one sacrifice, can make the difference between pain and salvation.\n\nThe two of us are gonna be working together for a bit.", objectives = "Read the Consecrated Rune and speak to Bromos Grummner in Anvilmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3108] = { id = 3108, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Etched Rune", description = "{name}, this rune was given to me to pass on to ye. Take some time to read it when ye have a chance. I'm thinkin' it came from the hunter trainer Thorgas. Take a gander at it and go find him inside Anvilmar.", progress = "Ya made it! Good to hear! Betcha didn't have to track me to find the place either. Haha!", completion = "One thing you should always remember is that you gotta respect the world you're livin' in. The beasts that choose to fight along side you; the shine of your weapon; the weight of your ammo; the bite of a bitter wind; all these things you need to know intimately.", objectives = "Read the Etched Rune and speak to Thorgas Grimson at Anvilmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3109] = { id = 3109, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Encrypted Rune", description = "{name}, this rune was given to me to pass on to ye. Take some time to read it when ye have a chance. I'm thinkin' it came from the rogue trainer Solm. Take a gander at it and go find him inside Anvilmar.", progress = "You made it! Great!\n\nWe've got an influx of activity lately, so I'm glad to count another of the Ironforge clan among our numbers. Nothin' like a cold blade in your hand and a shadow to keep you one step ahead, and if you're here, you know exactly what I mean!", completion = "Anyway, as you start peekin' around Coldridge you'll probably have need of training at some point. You just come back to me whenever you feel you need it and I'll teach you what I know--a trick here, a maneuver there. You know, the stuff that keeps you alive and makin' a little extra coin.", objectives = "Read the Encrypted Rune and speak to Solm Hargrin in Anvilmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3110] = { id = 3110, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hallowed Rune", description = "{name}, this rune was given to me to pass on to ye. Take some time to read it when ye have a chance. I'm thinkin' it came from the priest trainer Branstock. Take a gander at it and go find him inside Anvilmar.", progress = "Ach! Ya made it, {name}! Wonderful!\n\nI was gonna say, I was about to lose faith that ye'd arrive at all... get it, lose faith? It's a joke, lad... aww, nevermind. Ya didn't come here for me bad jokes anyway.", completion = "I'm the one who can train ya as you start to find your way around Coldridge Valley. When ya feel yer ready, come back to me and we'll see about maybe teaching you a new spell or two to fend off the valley from them blasted troggs.\n\nYa got the Light on yer side, along with all of Ironforge, {name}... no pressure on ya to become somethin' special.", objectives = "Read the Hallowed Rune and speak to Branstock Khalder in Anvilmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3112] = { id = 3112, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Simple Memorandum", description = "While you were helping me out, this memorandum was given to me to pass on to you. Take some time to read it when you have a chance. I'm thinkin' it came from the warrior trainer Thran. Take a gander at it and go find him inside Anvilmar when you've a chance.", objectives = "Read the Simple Memorandum and speak to Thran Khorman in Coldridge Valley.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3113] = { id = 3113, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Encrypted Memorandum", description = "While you were helping me out, this memorandum was given to me to pass on to you. Take some time to read it when you have a chance. I'm thinkin' it came from the rogue trainer Solm. Take a gander at it and go find him inside Anvilmar when you've a chance.", progress = "Glad to see you got my note and came over. Sorry about pretendin' it was a memorandum from your higher-ups... no offense intended. I just knew the two of us, along with others of our kind, gotta stick together.\n\nNot many think it's the best thing in the world to have your kind and my kind holed up in the same city, but I think we can work things out just fine. What do you think?", completion = "I pretty much keep to myself around here so we don't get a bad rap for things gone missing, but if you need anything, some training or somethin', just come back anytime.\n\nYou and me got an understandin'. We know when it comes down to it you can only trust family... and that's just what we got going on here, isn't it? Regardless of Gnomeregan being... overrun, and whatever else is thrown our way, we got one another to back each other up. Right?", objectives = "Read the Encrypted Memorandum and speak to Solm Hargrin in Coldridge Valley.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3114] = { id = 3114, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glyphic Memorandum", description = "While you were helping me out, this memorandum was given to me to pass on to you. Take some time to read it when you have a chance. I'm thinkin' it came from the mage trainer Marryk. Take a gander at it and go find him inside Anvilmar when you've a chance.", progress = "Yeah, what's that, {race}? Speak up, if you don't mind. I don't hear so good after a few ales.", completion = "Oh, yeah! Arcane Arts... of course.\n\nHere's what you need to know, {name}: Don't get into too much trouble. Save some coin to buy me an ale... or any spells ya might want. And stay the heck away from Gnomeregan. Other than that, have a good day! I'll be here if you need me or want to train... or whatever.", objectives = "Read the Glyphic Memorandum and speak to Marryk Nurribit inside Anvilmar above Coldridge Valley.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3115] = { id = 3115, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tainted Rune", description = "While you were helping me out, this memorandum was given to me to pass on to you. Take some time to read it when you have a chance. I'm thinkin' it came from the warlock trainer Saripal. Take a gander at it and go find her inside Anvilmar when you've a chance.\n\nAnd watch yerself, {name}, your kind ain't too trusted 'round these parts.", progress = "Wonderful! You obviously got my rune.\n\nIgnore the fools around you, {name}. The Holy Light?! The sword and shield?! These aren't paths for ones as open minded as us.", completion = "But none of that matters. What matters is that you've seen your own Holy Light! You know where power truly comes from. You realize that having our own allies is much more... prudent. Special allies. Allies that, no matter the task, will obey till their last breath.\n\nAnd that's where I come in, {name}. I can train you in the beginnings of those special powers. Seek me out often and I will do what I can to teach you more spells.", objectives = "Read the Tainted Rune and speak to Saripal Smolderbrew inside Anvilmar above Coldridge Valley.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3116] = { id = 3116, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Simple Sigil", description = "This sigil was given to me by a messenger from our warrior trainer, Alyissia. It seems Alyissia would have words with you when you have a moment. Read it and bring it to her afterwards.", progress = "You made it. I'm so glad.\n\nMuch has happened over the last few years, {name}: the creation of Teldrassil, the corruption of many of the forest creatures here and abroad, discovery of lands we thought lost to us like Feralas... so much, in so little time. But those are just some of the reasons we are here, the most important being to protect our kind from further evil.", completion = "Soon you will see others from different races in the boughs of our home--do not let it cause any prejudice within you. They are welcome. They will aid us when they can. Not all of them will be altruistic, but they should be granted some amount of trust.\n\nBut none of this matters now. Now we must focus on you, and how you can aid our people. I am here for that very purpose. I will train you in the ways of a {class} as you become stronger. Return to me whenever you wish and I will do what I can to aid you.", objectives = "Speak to Alyissia inside Aldrassil in Shadowglen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3117] = { id = 3117, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Etched Sigil", description = "This sigil was given to me by a messenger from our hunter trainer, Ayanna. It seems Ayanna would have words with you when you have a moment. Read it and bring it to her afterwards.", progress = "You've arrived, and none too soon, {name}. Welcome to Shadowglen.\n\nI trust my sigil found you in good spirits and health?\n\nAs I said previously, I am here to train you as a {class}; to tame beasts to aid you in battle; to use a bow with unerring accuracy; to respect the lands which we call home and also the lands beyond.", completion = "As you experience what Shadowglen has to teach you, come see me--I will be able to help you understand more about your role as a {class} and what you are capable of.\n\nThese are dangerous times, {name}, do not take for granted the skill of your pets--there are things in this world more dangerous than you can imagine. Go with Elune and return to me again.", objectives = "Speak to Ayanna Everstride inside Aldrassil in Shadowglen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3118] = { id = 3118, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Encrypted Sigil", description = "This sigil was given to me by a messenger from our rogue trainer, Frahun. It seems Frahun would have words with you when you have a moment. Read it and bring it to him afterwards.", progress = "Hello, {name}. I'm glad you found me. I was thinking that perhaps you got lost on the way here.\n\nNothing really new has happened in Shadowglen since I sent you my sigil, but I'll leave all the information gathering to you. Speak to the rest of the people around Aldrassil if you'd like.", completion = "Until then, know that our kind are needed more than ever in this tenuous time. Peace with the other races can fail at any moment, and there is much talk about members of the Horde looking to sow even greater seeds of distrust. Remember that.\n\nAs you gain in power and feel more prepared, come back to me here and I will see about getting you some training. It's important that you know how to handle your weapon of choice, among other things.", objectives = "Speak to Frahun Shadewhisper inside Aldrassil in Shadowglen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3119] = { id = 3119, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hallowed Sigil", description = "This sigil was given to me by a messenger from our priest trainer, Shanda. It seems Shanda would have words with you when you have a moment. Read it and bring it to her afterwards.", progress = "It pleases me to see you've arrived so quickly, {name}. Welcome.\n\nAs you've probably heard, all of Teldrassil is stirring with the comings and goings of travelers. Even members of the Alliance have been allowed access onto Teldrassil's boughs in order to meet with other Kaldorei who prepare for the adventures ahead.", completion = "Do not concern yourself with the world below Teldrassil for now. There will be time for that later. Go now and speak to the others in Shadowglen--they can tell you more about what events have transpired. Help them in any way you can, and anytime you feel you need more training, come back to me and I will teach you what I can.", objectives = "Speak to Shanda inside Aldrassil in Shadowglen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3120] = { id = 3120, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verdant Sigil", description = "This sigil was given to me by a messenger from our druid trainer, Mardant. It seems Mardant would have words with you when you have a moment. Read it and bring it to him afterwards.", progress = "Ah, young {class}. I see you're eager to continue your studies. Good.\n\nI wonder, have you spent much time in the Emerald Dream already? Perhaps you're not prepared for that yet... In time, I'm sure.\n\nBut until then, we should discuss other matters.", completion = "I will be your mentor and guide for now. It is my duty to teach you how to interpret not only what the spirits communicate to us, but also the complexities and secrets of the Emerald Dream.\n\nAs you learn and grow in power, you will learn more of our sleeping trance. But until then, return to me as often as you like and I will teach you what I can in the ways of our kind.", objectives = "Speak to Mardant Strongoak inside Aldrassil in Shadowglen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3121] = { id = 3121, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Strange Request", description = "Xerash Fireblade, located at the Lariss Pavilion, north of Camp Mojache,  has what I need to get started here! He has mixed up a concoction that I need for my... well, you'll see.\n\nOff with you now -- to Xerash. Here, take this with you. It's a shrunken head that I promised Xerash in exchange for the herbs. It's the head of some poor dwarf I ventured across in the forest. I'm sure he will be pleased.", progress = "Yes?", completion = "I have been waiting for Uzer'i to deliver this...\n\nLet me give you the herb mixture I prepared for his... well, experiments...", objectives = "Take the Shrunken Head to Xerash Fireblade at the Lariss Pavilion in Feralas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3122] = { id = 3122, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Witch Doctor Uzer'i", description = "Here are the herbs, {name}. Take them to Witch Doctor Uzer'i.\n\nPlease let him know that I am satisfied with the shrunken head.", progress = "Have you spoken to Xerash?", completion = "This is just what I need to prepare the muisek vessel, {name}.  Soon we will see if my latest incantations prove to be as powerful as I had hoped.\n\nPlease, a moment. I must perform the ritual and apply the herbs.", objectives = "Deliver Xerash's Herb Pouch to Witch Doctor Uzer'i in Feralas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3123] = { id = 3123, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Testing the Vessel", description = "This will be a test; both of the ritual I performed, and of your abilities. Take this vessel, {name}. With it, you will have the power to shrink and capture a creature inside of it.\n\nTravel to the wilderness east of here and look for beasts. The vicious, ironfur bears and longtooth runners are your targets, {name}. Kill them, and use the muisek vessel to shrink and capture them before their spirits can escape.", progress = "Were you able to capture the beasts?", completion = "Upon a violent death, the muisek of a creature may escape and seek revenge. Shrinking the creatures, as you did, {name}, prevents the muisek from escaping. Now we may use it as we please!", objectives = "Kill 10 Ironfur Bears or Longtooth Runners, and use the Beast Muisek Vessel to shrink and capture the fallen beasts.\n\nBring 10 Beast Muiseks and the Beast Muisek Vessel to Witch Doctor Uzer'i in Feralas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3124] = { id = 3124, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hippogryph Muisek", description = "Since you have proven that you are both trustworthy and gifted with the ability to use the muisek vessel, I now wish you to capture another creature.\n\nHippogryphs have been loyal companions to the night elves for many years; their spirits are loyal and steadfast.\n\nYour task is to kill 10 frayfeather hippogryphs, and quickly, shrink and capture them with the vessel, so that their muisek may be preserved. You will find the hippogryphs in the High Wilderness, to the south of here.", progress = "Were you able to capture the hippogryphs?", completion = "After killing an animal, if we allowed the muisek to escape, it may take the form of an even greater creature. We would never be safe from its vengeance.\n\nThis is a dangerous job I have given you, {name}. Again, you have completed it well.", objectives = "Kill 10 Frayfeather Hippogryphs of any type, then use the Muisek Vessel to shrink and capture them.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3125] = { id = 3125, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Faerie Dragon Muisek", description = "{name}, next I must have you capture a creature that in appearance, may look quite fragile, yet its powerful spirit is what we are truly after. The faerie dragons that I speak of have served the night elves as their allies. We must capture one so that the horde may benefit from this strength of spirit as well.\n\nHere is the muisek, {name}. Kill 8 sprite darters or sprite dragons, and capture their muisek. They may be found to the west of here.", progress = "Were you able to capture the muisek of the faerie dragons?", completion = "Thank you, {name}. Now the spiritual powers of the faerie dragon will be available to us.\n\nI hope you willing to perform another task for me.", objectives = "Kill 8 Sprite Darters or Sprite Dragons. Use the Muisek Vessel to shrink and capture the fallen Faerie Dragons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3126] = { id = 3126, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treant Muisek", description = "The wandering forest walkers that can be found meandering through the forest are our next target, {name}. Night elves have enlisted treants as allies to fight against the horde. Their movement may be slow, but their role as protectors is undeniable.\n\nSoon we will be able to use this power for our own benefit.\n\nFind 3 wandering forest walkers; kill them, and use the muisek vessel to shrink and capture them.", progress = "Were you able to capture the wandering forest walkers?", completion = "Thank you, {name}. Our muisek collection is almost complete.", objectives = "Kill 3 Wandering Forest Walkers. Use the Muisek Vessel to shrink and capture the fallen Treants.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3127] = { id = 3127, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mountain Giant Muisek", description = "The last task I will require of you is to travel to the northwest and find the final enemy.\n\nThe mountain giants left the mountains to aid the night elves when the burning legion appeared in the world. You will know them by their massive size and the way the ground begins to shake as you travel along their rocky terrain.\n\nI am eager to harness power of that size. Kill 7 mountain giants, then use the muisek vessel to capture their powerful muisek.", progress = "Were you able to capture the mountain giants?", completion = "Just imagine the possibilities of what we now possess, {name}. Along with the materials that you have collected, I will be able to forever trap the muisek of these creatures into whatever I wish.", objectives = "Kill 7 Land Walkers or Cliff Giants. Use the Muisek Vessel to shrink and capture the fallen Mountain Giants.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3128] = { id = 3128, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Natural Materials", description = "I will need certain materials to complete my endeavor... You may do this alongside the other tasks I will give you.\n\nI'll need a splintered log from a treant of Feralas. Encrusted minerals, these can be found on the mountain giants and faerie dragons to the west. Also, find me some resilient sinew from the owlbeasts of the Hinterlands or hippogryphs of Feralas. Finally, I'll need a large amount of metallic fragments from any of these creatures I mentioned.", progress = "Were you able to collect the materials I need?", completion = "Excellent! These materials, combined with the muisek, should yield just the results we've been wanting.", objectives = "Bring 2 Splintered Logs, 6 Encrusted Minerals, 20 pieces of Resilient Sinew, and 40 Metallic Fragments to Witch Doctor Uzer'i in Camp Mojache.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3129] = { id = 3129, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weapons of Spirit", description = "Imbuing the muisek into the weapons is a difficult process. Now that I have all of the required materials and the muisek of the creatures that you captured, I may begin. Please wait; I will return in a moment.", completion = "As promised, you have your choice, {name}. The muisek of the creatures has been forever sealed into the power of these weapons.\n\nYou may now wield their energy as your own. Use it well.", objectives = "Witch Doctor Uzer'i wants you to wait for a moment while he prepares the weapons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3130] = { id = 3130, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Against the Hatecrest", description = "At this point, I am going to direct you to my second, Latronicus.  He's been keeping a close eye on the naga forces to date.  I'll assess the general situation here in regards to the naga; as much as I want to commit a full force to move against them, leaving the stronghold open to direct attack from the Horde - or worse - seems less than optimal.\n\nAnyway, Latronicus awaits.  Good work thus far, {name}.  Keep it up.\n\nYou're dismissed.", completion = "Excellent, {name} - I value a \"can do\" attitude in those who I work with.\n\nI've been tasked by General Feathermoon to address the naga in a direct manner.  My plans are two fold: one, we will weaken their forces both in number and in command, and two, we will uncover what they are up to in the ruins.  With your help, we'll counter the naga presence without sacrificing the general security of the stronghold.", objectives = "Report to Latronicus Moonspear in Feathermoon Stronghold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3141] = { id = 3141, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loramus", description = "So you wish to battle demons? You would do well to listen to my tale.", completion = "So be it...", objectives = "Listen to Loramus Thalipedes tell his story.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3161] = { id = 3161, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gahz'ridian", description = "{name}, I'm a scientist, but also a treasure hunter at heart!\n\nLong ago, when trolls used to occupy this land, they created large amounts of ornaments modeled after Gahz'rilla, a hydra they worshipped as a deity. These ornaments are carved out of an element that I call \"Gahz'ridian,\" after the hydra god.\n\nI did find some myself, but I'd like to have some more to study -- maybe you can find some?\n\nI even invented a detector that makes finding the Gahz'ridian a snap! Just put it on, and the search begins!", progress = "Are you having any trouble?\n\nYou can find Gahz'ridian just about anywhere in Tanaris, {name}, so keep looking!", completion = "Perfect; these ornaments are perfect for my studies. Thanks so much for the help, {name}.\n\nOh, can I get my helmet back?", objectives = "Marvon Rivetseeker in Tanaris wants you to collect 30 Gahz'ridian Ornaments.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3181] = { id = 3181, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Horn of the Beast", description = "The gigantic horn has numerous scratches and cracks. An unusual metal object is lodged into the rough surface.\n\nUpon further examination, you notice that the metal is actually a broken axe head. On the metal, the following words are etched:\n\nProperty of Mountaineer Pebblebitty.\n\nWhen you try and dislodge the broken axe head, it shatters into a million pieces.\n\nWoops!", progress = "No, I will not open the gate.", completion = "What have you got there? A fake obviously!\n\nI've been face to face with Margol and I know for a fact that her horn is at least eight times larger than the one you've got in your hands, {name}. You probably got that off of a stormsnout in the Barrens. No sir, you can't fool Pebblebitty!", objectives = "Take Margol's Gigantic Horn to Mountaineer Pebblebitty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3182] = { id = 3182, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proof of Deed", description = "You expect me to believe a story like that? The real horn would have had my broken axe head still lodged into its surface.\n\nListen, take that obvious fake to Curator Thorius in Ironforge. If he can validate your claim, you will receive a proof of deed. Bring that proof back to me and I'll give you the key to the Searing Gorge.\n\nGet going!", progress = "Why hello there young man. Would you like a tour of the museum?", completion = "What's this?\n\nOh my, I don't believe it! Do you realize what you've got here, {race}? This is the horn of Margol the Rager! Margol, the bane of every archaeologist that ever set foot in the Searing Gorge.\n\nMay I keep it?", objectives = "Take Margol's Gigantic Horn to Curator Thorius in Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3201] = { id = 3201, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "At Last!", description = "I can't believe Pebblebitty doubted the authenticity of the horn. Between you and me, I think she's just jealous. I know she really wanted to kill that beast herself, what with the 'incident' and all.\n\nSo you need a proof of deed? After the contribution you just made to the museum, it won't be a problem.\n\n<Curator Thorius begins to fill out a large document.>\n\nThere we go! You can take that back to Pebblebitty.", progress = "I don't believe it.", completion = "I don't know how someone as weak as you overcame Margol, but a deal is a deal. Here is the key.\n\nIf anything happens to you after this, it will be your own fault.", objectives = "Take the Proof of Deed back to Mountaineer Pebblebitty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3221] = { id = 3221, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speak with Renferrel", description = "While you were out helping our deathstalkers, Apothecary Renferrel sent you a summons.  He did not give me details, but he wanted to speak with you about the wolf hearts you had given him.", completion = "Ah, very good.  There is a matter regarding the wolf hearts you brought to me earlier that demands our attention.", objectives = "Speak with Apothecary Renferrel at the Sepulcher.While you were out helping our deathstalkers, Apothecary Renferrel sent you a summons. He did not give me details, but he wanted to speak with you about the wolf hearts you had given him.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3281] = { id = 3281, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stolen Silver", description = "You may have killed the raptors, but the silver they stole must be recovered!  I have reports that the raptors have a large grouping of nests south of Ratchet, known as the Raptor Grounds.  It is likely that they brought our stolen silver there.\n\nGo to this raptor haven and search for the stolen silver.  When you find it, return it to me.", progress = "Do you have the silver?", completion = "Aha!  So the raptors did hide the silver at their lair.  It's hard to believe these beasts would have the desire for silver.  Perhaps the stories of their intelligence are not as far from the mark as I thought!\n\nThank you, {name}.  Take this as a reward for your service to us, and know that the guards of the crossroads owe their next month's pay to you.", objectives = "Bring the Stolen Silver to Gazrog in the Crossroads.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3301] = { id = 3301, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mura Runetotem", description = "My clanmate, Mura Runetotem, traveled to Silverpine so that she might aid our undead allies.  Silverpine is an ailing forest, a dying forest, and it was Mura's hope to bring it new life.  Perhaps the strange life found here in the Barrens can help her work in Silverpine.\n\nTake a sample of the shells you gathered, and bring it to Mura in Silverpine.  She is staying at the Sepulcher.  With luck, studying the shell will give her the insight she needs to heal that dying place.", progress = "I can smell the dust of the Barrens on you, {class}.  You have traveled far.", completion = "Ah, what is this?  This shell has an inner glow, as if it still pulses with life.  Amazing!  I must study it further.\n\nThank you, {name}.  With luck, this shell will hold a secret I can use to aid the poor land of Silverpine.", objectives = "Speak with Mura Runetotem at the Sepulcher in Silverpine Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3321] = { id = 3321, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Did You Lose This?", description = "You have done much for the Order, {name}. The sheer dedication it takes to get this far would have turned away any ordinary person. There is no doubt in my mind, or in the mind of Galvan, that you are one of us.\n\nWhich is why I think you deserve a little reward. It is nothing really, just a trinket. You may be familiar with its properties, as I do believe it is what brought you to us in the first place.", completion = "Rise and be recognized, {name}, blacksmith of the Mithril Order.", objectives = "Wait for Trenton to finish his work.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3341] = { id = 3341, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bring the End", description = "In the Barrens lies a horrid mess of tangled vines called Razorfen Downs. While our first observations of this place revealed little threat, our recent findings are much more serious...\n\nThe quilboar of Razorfen Downs have aligned themselves with the Scourge. A Lich named Amnennar the Coldbringer rules them now, using the power of his massive consciousness to control their every move.\n\nAmnennar has a direct telepathic link to Ner'zhul; we must sever this bond, {name}. An end must come to the Coldbringer.", progress = "This matter is of utmost importance, {name}. We must stop any attempt by the Scourge to bolster their ranks.", completion = "The loyalty of a Lich is unswerving, {name}. Let them know that such loyalty will only bring them destruction.", objectives = "Andrew Brownell wants you to kill Amnennar the Coldbringer and return his skull.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3361] = { id = 3361, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Refugee's Quandary", description = "I was on my way to join my fellow gnomes at Gnomeregan, but then it all went so horribly wrong!\n\nI left Anvilmar, bags packed and wading through waist-deep snow.  Then we had this ridiculous earthquake, and I got all turned around.  I ended up here, and what's worse: the trolls stole all my stuff!\n\n{name}, I've obviously proven myself to be quite incompetent over the last day and a half.  Would you mind infiltrating the troll camps southwest of here and returning my stuff to me?", progress = "Once I get my tools, I'm outta here.", completion = "Huzzah, you've found them!  Get ready, women of Gnomeregan: here comes Felix!\n\nNow, which road takes me out of here...", objectives = "Obtain Felix's Box, Felix's Chest and Felix's Bucket of Bolts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3362] = { id = 3362, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thistleshrub Valley", description = "Have you ever seen Thistleshrub Valley? It's a mighty dangerous place, {name}.\n\nThose strange beasts there, I don't trust them for a minute! Gnarled thistleshrubs and thistleshrub rootshapers, that's what I think they were called...\n\nAnyhow, I want to get into the valley, but with so many of those thistleshrubs around, there's no way I'm going back there. But here's where you come in -- if you clear some of them out, I just might think about going back. What do you think, {name}? Help me out?", completion = "They're that big? I might have to rethink my plan...\n\nBut you did hold up your end of the bargain, so here's what I promised.", objectives = "Tran'rek in Gadgetzan wants you to kill 8 Gnarled Thistleshrubs and 8 Thistleshrub Rootshapers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3363] = { id = 3363, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corrupted Songflower", progress = "You have found a sickly, corrupted version of what appears to be a songflower plant. A pungent, unhealthy odor emanates from the plant. It desperately needs some sort of attention if it is to be turned back to normal.", completion = "You apply some Cenarion plant salve to the songflower. It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant." }
quests[3364] = { id = 3364, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scalding Mornbrew Delivery", description = "Gah!  I was supposed to get this delicious scalding mornbrew to Durnan Furcutter inside Anvilmar a while ago now, but I had to deliver one to Grelin here first.  I'll never make it to Anvilmar before the brew runs cold!\n\nYou look fast.  Maybe you can make it.  This cup will only stay hot for five more minutes, and Durnan didn't order \"chilly\" mornbrew, so get going.  Anvilmar is to the northeast, a settlement dug into the mountain.\n\nThanks, {name}, and don't forget to bring me back my mug!", progress = "Aye, I'm Durnan Furcutter.  You have something for me?", completion = "Ah good, now this will hit the spot.  Allow me to take a small break while I enjoy this scalding mornbrew!", objectives = "Take a Scalding Mornbrew to Durnan Furcutter inside Anvilmar before it gets cold in five minutes!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3365] = { id = 3365, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bring Back the Mug", description = "Now that hit the spot!  Nothing like a piping hot - nay, SCALDING mornbrew on a cold winter's day to warm your cackles of yer soul.\n\nHere ya go {name} - be a pal and take this empty mug back to Nori for me, would ya now.", progress = "I trust the scalding mornbrew got to Durnan on time!  Did you remember to bring me back my mug?", completion = "Excellent, {name}!  You'd be surprised how many couriers I meet who forget to do something as simple as bring back the mug.  Mugs don't grow on trees, or so they tell me!\n\nHere's a little something for the effort.  Thanks again for your help.", objectives = "Return Nori's Mug to Nori Pridedrift in Coldridge Valley.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3366] = { id = 3366, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Glowing Shard", description = "The shard is a brilliant green, and although solid, what looks like smoke swirls just below the surface. You can't help staring into the depths of the crystal; at the same time, you know there is something very disturbing about it.\n\nMaybe you should see if anyone in Ratchet can tell you more about this strange shard.", objectives = "Travel to Ratchet to find the meaning behind the Nightmare Shard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3367] = { id = 3367, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suntara Stones", description = "<Dorius groans.>\n\nI'm badly injured, {race}. Feel... light headed... World spinning... Bleeding... internally.\n\nI must get back to Ironforge. Help me, {name}.", completion = "This letter was dropped by Dorius when he was shot.", objectives = "Help Dorius get back to Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3368] = { id = 3368, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suntara Stones", description = "Brother,\n\nIf you are reading this letter, I am no more. How it got to you, I do not know, but thank and reward the ones responsible.\n\nAbout the stones: They exist and the Dark Irons have them in their possession. Their leader, Lathoric the Black, is using the power of the stones to enslave my excavation team. They were taken to the cauldron. Their minds are twisted, working night and day to complete something called Obsidion.\n\nHelp them, brother. It is the final wish of a dead man.\n\n-Dorius", progress = "<Thorius sobs.>", completion = "<Thorius wipes his face dry.>\n\nIn the name of the Light, he will have his wish. This I vow.", objectives = "Take the Singed Letter to Thorius in Ironforge. He is in the Hall of Explorers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3369] = { id = 3369, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Nightmares", description = "This shard holds great secrets; it is the pure essence of the Emerald Dream. However, what I see in this shard is not a dream; one would call this sort of a vision a nightmare.\n\nI do not wish to alarm you, {name}, but I think it is best if you deliver this shard into the hands of a wise druid as soon as you can.\n\nHamuul Runetotem on Elder Rise is who you need to find. Head to Thunder Bluff. I cannot say more.", progress = "May I help you with something?", completion = "Falla sent you to me? Well now, let's see that shard that you say she was so hesitant to talk about...\n\n<Hamuul peers into the shard>\n\nOh... I didn't... Well.\n\n{name}, thank you for delivering this to me. It isn't wise to speak of things such as this, though, I advise you. These are matters that you should not concern yourself with.\n\nLet's just say that things in the Emerald Dream are not as we thought...\n\nPerhaps in the future, our paths may cross again.", objectives = "Bring the Nightmare Shard to Hamuul Runetotem on Elder Rise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3370] = { id = 3370, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Nightmares", description = "This shard holds great secrets; it is the pure essence of the Emerald Dream. However, what I see in this shard is not a dream; one would call this sort of a vision a nightmare.\n\nI do not wish to alarm you, {name}, but I think it is best if you deliver this shard into the hands of a wise druid as soon as you can... \n\nMathrengyl Bearwalker in the Cenarion Circle is who you need to find. Head to Darnassus. I cannot say more.", progress = "May I help you with something?", completion = "Falla sent you to me? Well now, let's see that shard that you say she was so hesitant to talk about...\n\n<Mathrengyl peers into the shard>\n\nOh... I didn't... Well.\n\n{name}, thank you for delivering this to me. It isn't wise to speak of things such as this, though, I advise you. These are matters that the Cenarion druids alone must attend to.\n\nLet's just say that things in the Emerald Dream are not as we thought...\n\nPerhaps in the future, our paths may cross again.", objectives = "Bring the Nightmare Shard to Mathrengyl Bearwalker in Darnassus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3371] = { id = 3371, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dwarven Justice", description = "There is an empty, vacuous hole, where my heart used to be, {name}. The loss of Dorius is not one that I will soon recover from. I must see his final wish through - the perpetrators of this cold blooded murder must be brought to justice.\n\nReturn to the Searing Gorge and fulfill his last request: Free his men. The Dark Iron dwarves force their slaves to work in a sweltering mine called the Slag Pits. Search there for Dorius' men.", sourceObjective = "Return to the Searing Gorge and find Dorius's archaeology unit.", completion = "Forget about me, help the others.", sourceObjectiveStatus = "unverified-source-field" }
quests[3372] = { id = 3372, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Release Them", description = "Release them, {race}. Even after their bodies give out, the power of the Suntara forces them to complete their tasks.\n\nThe altar of Suntara is the key. Go northwest; in the hills above the cave... Twilight's Hammer guard a relic. Retrieve it and place it on the altar of Suntara.\n\n<The dying archaeologist collapses.>", progress = "The altar is empty.", completion = "You place the mysterious artifact on the altar of Suntara.", objectives = "Find the Mysterious Artifact being guarded by the Twilight's Hammer Idolaters in the northwest quadrant of the Searing Gorge and bring it to the Altar of Suntara in the Slag Pit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3373] = { id = 3373, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Essence of Eranikus", description = "As you touch the gem, a deep voice resonates in your mind.\n\n\"Mortal, heed this plea.  I am Eranikus of the Green Dragonflight, keeper of this accursed temple.  My charge to ensure that the trolls never again bring forth their abomination of a god has for now ended in failure.  As I imbue this gem with part of my essence, I sense my grip on the Dream twisting into chaos.  Please - place this gem into the essence font in my lair, and let our magic there purge the taint from my psyche so that I may rest.\"", progress = "As you near the essence font that Eranikus told you of, his voice once again touches your mind.\n\n\"Yes mortal, this essence font will redeem what untainted element of my psyche remains imbued in this gem.  Place the gem inside the font, and let the magic of the Green Dragonflight cleanse the corruption and taint from my being.  Only then will I find true release, and only then will the Dragonflight be able to reassert their stewardship over the Atal'ai.\"", completion = "You place the gem inside the essence font.\n\n\"Thank you mortal, you have - no... this, this cannot be! No!  The corruption of this accursed god even taints the sanctity of a Green Dragonflight essence font!  No please, I feel my essence ripping from me!  THE PAIN!  I feel the grip of an eternal nightmare taking hold on me...\"\n\n\"Mortal, I implore you!  Find one of the Green Dragonflight to stop this... help me... I am chained in darkness... forever in agony... please do not torture...\"", objectives = "Place the Essence of Eranikus in the Essence Font located in this lair in the Sunken Temple.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3374] = { id = 3374, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Essence of Eranikus", description = "You engage the Oathstone, and Itharius speaks directly to your mind through the stone.\n\n\"By accepting the charge placed in this Oathstone, you agree to aid my cause and the cause of Ysera's Dragonflight in redeeming the corrupted soul of Eranikus.  The first sacrifice, one of many you and I will no doubt make, will be to relinquish the gem to me that has chained what free-willed part of Eranikus' psyche remains.\"\n\n\"Do this {name}, and we will work together to redeem a soul worthy of redemption.\"", progress = "Here we are {name}, at yet another crossroads.  The time has come to make another choice.  What choice do you make, mortal?", completion = "You have made your choice, and so it begins.  Your choices have been, to date, what I would consider to be the correct ones; your actions and deeds henceforth will determine whether this is to continue.", objectives = "Bring the Oathstone of Ysera's Dragonflight and the Chained Essence of Eranikus to Itharius in the Swamp of Sorrows. It is there that you will make your choice to aid Ysera's Dragonflight or not.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3375] = { id = 3375, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Replacement Phial", description = "Um... you need another phial of scrying?  You're kidding, right?  What did you do with the first one?!  We have a lot of work ahead of us here, {race}.  Those phials don't grow on trees!  Actually, I wish they did, because I'd go there and pick one off since I don't have another one!!\n\nin order to make you one, I need the following: a mana potion, a piece of coal, and some sweet nectar.  Don't ask why, just bring me what I ask and I'll make you a new one.", progress = "To make another phial I need a mana potion, a piece of coal, and some sweet nectar.\n\nThat, and a whole lotta patience apparently.", completion = "The mighty adventurer delivers.  Hooray for me.  By the way, I lied - I had another phial.  Ungh, take it.\n\nWell, what did you expect?!  \"Oh, here, have another one!  I'm just some goofball who has nothing better to do than hand out magical communication devices to adventurers!\"  Rest assured though, what you have given to me will be enough make you another phial when you lose that too.\n\nPlease prove me wrong and don't lose the new one, okay?", objectives = "Bring a Mana Potion, Coal, and Sweet Nectar to Talvash del Kissel in Ironforge to get a replacement for Talvash's Phial of Scrying.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3376] = { id = 3376, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Break Sharptusk!", description = "{name} - I have heard of you, newcomer.  Perhaps it is you that will help us, where others have failed.\n\nWe tauren have carved a home out of this land, but not without a cost.  The Bristleback quilboars of Brambleblade Ravine, led by Chief Sharptusk Thornmantle, have made our lives difficult with their continued war against us.  I charge you to bring me the chief's head!\n\nHe will be found in the ravine to the east in their makeshift village.", progress = "Sharptusk will trouble us no more once you have brought me proof of his death.  It is his head that I seek, {name}.\n\nWe {race} live for the hunt, and there is no greater hunt than against one that is cunning enough to perhaps hunt us back.  If you are successful in this task, young one, you will start to learn what I mean.", completion = "Justice has been served on this day by your swift actions, {name}.  Let this deed serve as a warning to all who would threaten our home.\n\nYou have earned this reward to help you on your sojourn, young {class}.", objectives = "Bring the head of Chief Sharptusk Thornmantle to Brave Windfeather in Red Cloud Mesa.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3377] = { id = 3377, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prayer to Elune", description = "Will you assist me, mortal? Hear my tale.", completion = "I have accepted my fate here in this cage, but the prayer must be found.", objectives = "Hear Zamael tell his tale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3378] = { id = 3378, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prayer to Elune", description = "Will you assist me, mortal? Will you find the prayer to Elune?\n\nAs I stated, the prayer was etched onto a golden tablet. One of these idol worshipping scoundrels must have it on their person.\n\nIf you do recover my prayer, take it to Astarii Starseeker in Darnassus. It matters little that my faith has been rekindled after the countless malevolent actions that I have taken against this world and its inhabitants, but my prayer must be heard. Absolution is the last thing I expect.", progress = "What brings you to the Temple of the Moon, {name}?", completion = "Elune smiles upon you this eve, {name}. You have returned a lost soul to her. Please accept this as a token of our gratitude.", objectives = "Find the Prayer to Elune and take it to Astarii Starseeker in Darnassus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3379] = { id = 3379, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadoweaver", description = "The spiders of the Searing Gorge are an invaluable source of shadow silk. As you know, shadow silk is highly sought after by the artisans of our trade.\n\nRecently, a group of poachers has encroached upon these lands, carelessly slaying spiders en masse without so much as a thought as to the long term effect of their actions. The first task I ask of you, then, is a simple one: Find them... and end them.\n\nBegin your search to the north.\n\nIf you require assistance, speak with Raze.", completion = "Excellent work, {name}.\n\nI am sure that this is a piece of shadoweave that you have not yet seen.", objectives = "Kill the group of Shadow Silk Poachers that wander the Searing Gorge. Nilith has reason to believe that there are five of them that need to be exterminated. Return to Nilith in the Searing Gorge when this task is complete.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3380] = { id = 3380, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sunken Temple", description = "There are restless spirits in this world, {name}. There are spirits that have been tainted by their isolation, bound to an ancient evil...\n\nI have heard of a place that lies deep below the surface of the earth -- banished there by powers greater than I have ever seen.\n\nIf you wish to learn more of this place; the Sunken Temple, seek out a goblin named Marvon Rivetseeker. He has studied many ancient areas of the world, and was last known to have left his home in Ratchet to study the troll ruins in Tanaris.", completion = "Yes, the Sunken Temple, I can say that I have seen it with my own eyes. Perhaps you'd like to hear more about it?\n\nYou look like the adventurous type -- I know things that may intrigue you...", objectives = "Find Marvon Rivetseeker in Tanaris.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3381] = { id = 3381, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Meeting with the Master", description = "Ah, a young {race} come to speak to Sanath. What a wonderful day! I am so honored to have you grace me with your presence. Thank you!\n\nPlease... do not be so arrogant to assume my sarcasm was a compliment. Let us get one thing straight: I don't like you. But this little conversation doesn't have anything to do with us--it has to do with my master.\n\nBring me a couple hippogryph feathers for my arrows and I'll give you leave to see him. He's asked that I send adventurers to him if they proved worthy enough.", objectives = "Bring 2 Undamaged Hippogryph Feathers to Sanath Lim-yo in Azshara if you wish to speak to his master.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3382] = { id = 3382, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Crew Under Fire", description = "We were just off the coast looking for a safe haven to make anchor. The sun hadn't been down for more than an hour when they attacked... those damned naga!\n\nI'm not sure what they were looking for, but it's clear they didn't find it--they've already come back once. A couple of my scouts are on watch at the entrance of the valley to give us fair warning when the next attack comes.\n\nI'm sorry you've come along now, {name}, but it's out of my hands.\n\nAre you ready for the fight of your life?", completion = "You've done it! Thank you! Surely this was one of the most brutal battles I've ever taken part in. I can't thank you enough.\n\nI only wish more of my crew could have lived through this trial.\n\nI would ask you to speak to any surviving passengers from the Horizon Scout. Some of them had business in the area, and may have a request or two of you if you're willing. Again, thank you for all your help.", objectives = "Defend Captain Vanessa Beltis, her crew and the Horizon Scout's passengers against the naga attack. Captain Vanessa Beltis must survive.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3385] = { id = 3385, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Undermarket", description = "They call themselves the Undermarket: Cutthroat traders that will sell, move, trade and do just about anything for the right price.\n\nIt gets worse, {name}. They have set up a base of operations here in the Searing Gorge. Trade Master Kovic is heading up the operation and has close ties with the Dark Iron dwarves of the region.\n\nWe must strike hard and send a message to their leadership. Slay Trade Master Kovic and his minion Clunk. Bring back his trader's satchel when the job is done.\n\nTo the Cauldron!", objectives = "Slay Trade Master Kovic and his minion Clunk. Retrieve the Trader's Satchel from his corpse and return it to Nilith.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3402] = { id = 3402, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Undermarket", description = "I want you to personally deliver the news of Kovic's defeat to Vizzklick in Gadgetzan. He will be so happy to hear that Kovic is dead that I'm certain he'll give you some grand reward.", sourceObjective = "Speak with Vizzklick in Gadgetzan.", completion = "Kovic slain??! This is a glorious day, {name}! For years that scoundrel has been running shady undermarket trades, undercutting honest, hard working traders all over the world.\n\nYou deserve a fine reward for this accomplishment! And a fine reward you shall have!", sourceObjectiveStatus = "unverified-source-field" }
quests[3421] = { id = 3421, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return Trip", objectives = "I will return you to Sanath's camp now.\n\nDo not mind his bad manners--he is rude to everyone save for the master. Perhaps he shall learn his lesson one day.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3441] = { id = 3441, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Divine Retribution", description = "Hear my tale, adventurer.", completion = "Have you heard enough? Are you prepared to act?", objectives = "Listen as Kalaran Windblade tells his story.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3442] = { id = 3442, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Flawless Flame", description = "You have made the right decision, {name}.\n\nWe must strike where we will do the most damage: the four sentry towers.\n\nWith the four towers in flames, we can initiate an offensive before they have time to react.\n\nYou will need the proper tool to set the towers ablaze. To make the tool requires some materials.\n\nBring me four hearts of flame and four golem oil and I shall craft the torch of flawless flame.\n\nThe golems and elementals in these lands should be your first target.", progress = "Have you collected the materials?", completion = "Well done, {name}. We are almost ready.", objectives = "Collect 4 Hearts of Flame and 4 globes of Golem Oil and return the items to Kalaran Windblade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3443] = { id = 3443, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forging the Shaft", description = "To hold the flawless flame, we will need a shaft and a casing. You must first find a suitable shaft.\n\nThe Dark Iron taskmasters and slavers of the cauldron use weapons of enchanted thorium, an extremely sturdy alloy. If you bring me eight thorium plated daggers, I can break the alloy down and reforge a shaft.", progress = "Eight, {name}. I need eight!", completion = "You're an exceptional laborer, {name}. Have you ever considered a change of vocation? Perhaps a detective? Junk collector? Oh, I know, one of those silly gnomes that crawl across the beaches of Azeroth with their metal detecting contraptions, looking for lost treasure. Yes, that would be an ideal position for you.", objectives = "Bring 8 Thorium Plated Daggers to Kalaran Windblade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3444] = { id = 3444, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Stone Circle", description = "I once entered the foreboding chambers of the Sunken Temple. The evil in that place penetrates all that enter; I barely managed to find my way out, wading through the ooze that now covers the floors. All I can remember is stumbling through a large circular room, filled with serpent statues...\n\nRecently, I discovered a round stone that appeared to have the same serpent symbol imprinted on it. I had it packed up and shipped to my workshop in Ratchet. Retrieve it, and I might be able to tell you more.", progress = "Ratchet is not far from here, {name}. The journey shouldn't take long.", completion = "Yes... This is the stone.\n\nIt's all coming back to me now, {name}...", objectives = "Retrieve the Stone Circle from Marvon Rivetseeker's workshop in Ratchet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3445] = { id = 3445, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sunken Temple", description = "I have heard of a place that lies deep below the surface of the earth -- banished there by powers greater than I have ever seen.\n\nIf you wish to learn more of this place; the Sunken Temple, seek out a goblin named Marvon Rivetseeker. Much like Troyas and I, he has studied many ancient areas of the world. He was last known to have left his home in Ratchet to study the troll ruins in Tanaris.\n\nGood luck finding him; he hasn't been heard from in some time.", sourceObjective = "Find Marvon Rivetseeker in Tanaris.", completion = "Yes, the Sunken Temple, I can say that I have seen it with my own eyes. Perhaps you'd like to hear more about it?\n\nYou look like the adventurous type -- I know things that may intrigue you...", sourceObjectiveStatus = "unverified-source-field" }
quests[3446] = { id = 3446, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Depths", description = "Inside the temple, I found a circular room with six balconies, each one with a serpent statue on the edge. Curious, I pushed one of them to see what would happen, and it was a trap! I nearly fell to my death from the explosion. Laying there on the ledge, I looked down and noticed that there was another statue at the base of the room; an altar of sorts... Hakkar, I think it was called.\n\nI think that this altar is the secret -- you must bring this token to the altar in the Sunken Temple.", progress = "Upon examining the statue, you notice a depression in its side, just the size of the token that Marvon gave you...", completion = "You push the stone circle into the opening, and you hear it lock into place.\n\nNow that the stone is in place, you may continue... but what should you do next?\n\nPerhaps you should examine this altar further...", objectives = "Find the Altar of Hakkar in the Sunken Temple in Swamp of Sorrows.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3447] = { id = 3447, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secret of the Circle", description = "My memories are cloudy, but I will tell you what I can. The circle of statues in the Sunken Temple, while dangerous, I believe that they hold the secret to unlock an even greater treasure.\n\nFrom the main altar, I was able to activate a series of lights. I think that if you can uncover what these lights mean, you might be able to unlock whatever secrets are hiding in this room.\n\nI warn you though, {name}. Great evil lies in the temple. It's likely that anything valuable will be fervently guarded...", sourceObjective = "Travel into the Sunken Temple and discover the secret hidden in the circle of statues.", completion = "The eye of the idol glitters brightly even in the half-darkness of the temple. Its transparency reveals something shiny behind it. Sliding it to the side, you reach in and grasp what lies inside the statue.\n\nThe Atal'ai treasure is now yours.", sourceObjectiveStatus = "unverified-source-field" }
quests[3448] = { id = 3448, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Passing the Burden", description = "I've recently been handed the responsibility of investigating Azshara--a once beautiful area the elves called home. This would be back when they practiced magic. It's now a more dangerous place than it is beautiful, but that doesn't stop us from turning over every stone for answers to our past.\n\nA companion of mine named Tymor offered to help me investigate the area since he takes a particular interest in such things.\n\nHe owns a small place to the right of the Hall of Mysteries here in the city.", sourceObjective = "Speak to Tymor in Ironforge.", completion = "Ah, Karnik sent you, did he? I expected to hear from him soon. I've discovered such wonderful things about Azshara.. I know night elves have incredible life spans, but everyone forgets some of the more... unfortunate events in their lives sometimes. That's not meant as a criticism, just an observation.\n\nLong ago, there were cities created by the elves filled with knowledge about magic and other lost arts. Being a student of such things, I started my investigation. What I found was quite thrilling.", sourceObjectiveStatus = "unverified-source-field" }
quests[3449] = { id = 3449, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arcane Runes", description = "Magic was once as revered as Elune herself to some elves. Some of their most powerful mages created runes and tablets citing rules of the arcane and insights into their findings. They would leave these for all to ponder in public places.\n\nI would very much like rubbings of these runes from the Ruins of Eldarath. I have a kit for you to make the rubbings with, but it will be up to you to find them. Be careful though, the Explorer's League isn't the only one interested in Eldarath.", progress = "Well, well, well, glad to see you made it out here, {name}. Did you get the rubbings for Tymor?\n\nAs dangerous as this place is, there hasn't been too much action along the coast. That might be on account of the naga swimming underwater, but that's not my problem... I patrol the skies.", completion = "Good to see you safe and sound, {name}. I hope things weren't too tough for you.\n\nI'll get these to Tymor right away. He'll be thrilled to take a look at these things.\n\nGo ahead and toss the flare gun... probably won't be any good to you anymore anyway, and I already got a new one.", objectives = "Using the Drawing Kit, make rubbings of the Rune of Beth'Amara, the Rune of Jin'yael, the Rune of Markri, and the Rune of Sael'hai before heading to the small island off of the southern peninsula of Azshara and signaling Pilot Xiggs Fuselighter to pick them up.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3450] = { id = 3450, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Easy Pickup", description = "I want the rubbings delivered to my tower, but there's no need to have you go all the way there. I'll just have them air-lifted out of Azshara.\n\nXiggs Fuselighter owes me a favor or two and will be in the area soon--he's signed on to patrol the coast. Speak to him before you leave. He can give you a flare gun to signal him with. When you have the rubbings, just head to wherever he tells you and then give them to him so he can get them to my tower safely. He should be in the hangar in the Military Ward.", sourceObjective = "Speak to Xiggs Fuselighter in Ironforge.", completion = "What can I do for you, {name}? Kinda busy at the moment preparing my ship for a long trip. I just came over to see some of the tank pilots--I need some wendigo manes to line my cockpit and they usually have extra.\n\nI can give you a minute if you're brief... one of the boys just took off to Steelgrill's Depot to see if the pilots down there have extra manes for me.", sourceObjectiveStatus = "unverified-source-field" }
quests[3451] = { id = 3451, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Signal for Pickup", description = "Ah, so Tymor sent you, huh? Yeah, I owe him a favor or two. What's that? Why, that little devil. Yeah, I can help him out with that. So you'll need a flare gun and a location... easy enough.\n\nThere's a small island off the southern peninsula of Azshara that we've made a landing pad on. You take this flare gun, and use it there. I'll see your signal and come by to pick up this... whatever it is he wants.", sourceObjective = "Speak to Xiggs Fuselighter and get a Standard Issue Flare Gun from him in Ironforge.", completion = "Here's my standard issue flare gun, and be patient after you fire off the gun--there are only a couple charges in one of these, and it might take me a minute to get to you depending on how far out to sea I am. Just look out to sea after you fire off the flare.", sourceObjectiveStatus = "unverified-source-field" }
quests[3452] = { id = 3452, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Flame's Casing", description = "We need one final piece to form the torch.\n\nIn the mountains to the northwest you will find a large encampment of Twilight's Hammer. It is rumored that they carry symbols and idols that pay homage to their god. These symbols and idols could carry sufficient enchantment to form a magical casing. Bring me a single symbol of Ragnaros and I will try to extract the magic from the item to create the casing.", progress = "Without a suitable source of arcane energy, the torch of retribution cannot be completed.", completion = "The symbol radiates foul magic; perfectly suited for our task.", objectives = "Find and return a Symbol of Ragnaros to Kalaran Windblade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3453] = { id = 3453, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Torch of Retribution", description = "Give me a moment to combine the pieces and apply the necessary enchantments.", completion = "There is one final task that you must complete.", objectives = "Wait for Kalaran Windblade to complete the Torch of Retribution.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3454] = { id = 3454, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Torch of Retribution", description = "The torch must now be bound to its owner. Pick up the torch, {name}.", sourceObjective = "Take the Torch of Retribution.", completion = "You grab the torch with both hands; waves of hatred and anger pulse through your being.", sourceObjectiveStatus = "unverified-source-field" }
quests[3461] = { id = 3461, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Tymor", description = "Tymor didn't give me anything to pay you with, so I suggest you take it up with him when you get back to Ironforge. I'm sure he'll still be in his place in the Mystic Ward. Just go knockin' and make sure he pays you good. This place ain't no picnic... that's for sure.\n\nThanks again for helping him out though, and good luck.\n\nOh, and I don't need the drawing kit. Why don't you just bring it back to Tymor when you go to see him?", progress = "You're back! Excellent. Do you have my drawing kit also?", completion = "Wonderful! I'm so glad to hear it.\n\nI'm really excited to get to my tower and go over those rubbings. I'm so envious of you... going to a place like Azshara. That's any student of the arcane's dream, I would guess.\n\nWell, we never spoke about any kind of reward since you were just working for the Explorer's League, but you deserve something.", objectives = "Return Tymor's Drawing Kit to him in Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3462] = { id = 3462, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Squire Maltrake", description = "Speak with my envoy, Squire Maltrake. He will further instruct you as to the use of the Torch of Retribution.", sourceObjective = "Speak with Squire Maltrake.", completion = "Are you prepared to make your strike?", sourceObjectiveStatus = "unverified-source-field" }
quests[3463] = { id = 3463, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Set Them Ablaze!", description = "Listen well, {name}. While the four towers can never be destroyed, you can use the torch of retribution to set them ablaze for a very long period of time: A fire that no element or force can subdue.\n\nWhile they are ablaze, no guard or sentry unit can inhabit the watch posts and thus, their first line of defense is nullified.\n\nYou must enter each tower and use the torch of retribution within their fortifications. Beware the lookouts posted by the Dark Irons, {name}.", completion = "It is glorious! Is it not glorious master?", objectives = "Set the North, South, East, and West Sentry Towers on fire by using the Torch of Retribution inside each of the buildings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3481] = { id = 3481, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trinkets...", description = "The chest appears locked.", sourceObjective = "Open the chest.", completion = "The chest opens at your touch. How much cheese could possibly be in here? There is only one way to find out.", sourceObjectiveStatus = "unverified-source-field" }
quests[3483] = { id = 3483, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Signal for Pickup", sourceObjective = "Ah, another flare gun, huh? That I can do.\n\nAnd don't forget, southern tip of Azshara. It's a small little island that's been turned into a landing pad. You can't miss it if you're in the right spot.", sourceObjectiveStatus = "unverified-source-field" }
quests[3501] = { id = 3501, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Everything Counts In Large Amounts", description = "Although you may never find a flawless sphere of draenethyst, you will undoubtedly uncover various imperfect fragments of the draenethyst in your exploration of these lands.\n\nWhile it is doubtful that Kum'isha will be able to use the flawed fragments to return home, the pieces may serve other, useful purposes for the draenei.\n\nReturn any piece of flawed draenethyst fragments that you may find and I shall reward you.", progress = "Have you had any luck in your exploration?", completion = "You truly disgust me, {race}. A grown man drooling over a pile of junk? Pitiful! Take your reward and get out of my sight.", objectives = "Bring Kum'isha Imperfect Draenethyst Fragments and be rewarded for each one you turn in.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3502] = { id = 3502, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Draenei's Junk...", description = "Well, after that display of voracious greed, I feel nauseous.\n\nRegardless, I shall not dwell too long on your material addiction.\n\nFor each imperfect draenethyst fragment you turn in, I shall reward you with more junk. My junk heap gets smaller while your junk heap gets larger. On Draenor we call this a 'win-win' situation.", progress = "Well? Draenethyst? Remember?\n\n<Kum'isha clenches his fist and knocks on your head.>\n\nIs anybody home?", completion = "You truly disgust me, {race}. A grown man drooling over a pile of junk? Pitiful! Take your reward and get out of my sight.\n\nSounds familiar? It should, because I say it a thousand times per day.\n\nOh how I loathe this world.", objectives = "Bring Kum'isha Imperfect Draenethyst Fragments. Any form of monster in the Blasted Lands could be carrying a fragment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3503] = { id = 3503, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meeting with the Master", objectives = "There was a time when I could ask whatever I wished from those who sought out my master.  But now, you need only ask and I will send you to him.\n\nIt is upsetting to me, but I do not question his orders.  I can only take enjoyment in making fun of the ridiculous clothes you wear or the pathetic look on your face.  Even that bores me...\n\nEven this rambling bores me!  Do you wish to see my master or not?", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3504] = { id = 3504, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Betrayed", description = "Betraying, thieving woman! That's what I call her--that's all she'll ever be!\n\nI may have made a grave mistake, {name}. I trusted a blood elf. What's worse, I trusted a woman!\n\nShe claimed Azshara would hold great riches... powerful items. I simply send some warriors with her to protect her and I would be rewarded. Well, look who's the fool--she's killed them all.\n\nI want vengeance, {name}, but I can't afford to send anyone else. Find Ag'tor at Valormok, north of the Haldarr Encampment. He'll tell you more.", progress = "Ah, Belgrom wizened up and finally sent someone not in his ranks to aid us, did he?\n\nThis camp used to be a dozen warriors strong, {name}, but now they're all dead. That mage, Rimtori, has slain them all. She played Belgrom like a lute... seduced him even. It's none of my business, but between you and I, she is quite the temptress. That's probably why I'm still out here helping Belgrom--I probably would have done the same thing.", completion = "We've sent everything we had at her and her workers, but they are strong in battle. None have bothered to return. I'm assuming some have died, but I'm sure others simply ran... cowards.\n\nBut now that reinforcements have arrived, perhaps there's still something we can do. Perhaps we can still punish her for lying and betraying Belgrom.\n\nWhat do you say, are you in?", objectives = "Deliver the Sealed Letter to Ag'tor to Ag'tor Bloodfist in Azshara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3506] = { id = 3506, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Betrayed", description = "A few more moments of thought brings a few ideas to mind, one of which brings a smile to your face: perhaps destroying the crystals would upset the blood elf responsible for the slaughter of so many orcs and the betrayal of Belgrom?\n\nYou continue to decipher more of the script and pictures and realize that one of the crystals is tied to the creator of the circle--the others are tied to something far more sinister.\n\nYou close the book and begin to decide which crystal to destroy.", progress = "How goes your slaughter of the blood elf traitors, {name}? Have you made any progress?\n\nI hope you are the one strong enough to bring that dog to her knees! She deserves nothing but a painful death for all that she has done!", completion = "RAR!! Incredible!\n\nYou've done it! Belgrom will be pleased! Finally the spirits of dozens of our warriors can be at peace. Thank you, {name}.", objectives = "Destroy the arcane focusing crystal tied to Magus Rimtori and then slay her. Afterwards, take the Head of Magus Rimtori to Ag'tor Bloodfist in Azshara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3508] = { id = 3508, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking the Ward", description = "You are foolhardy, {name}. It is an admirable quality of your kind - to blindly enter battle when you have little to no chance of success. I will assist you, if only to see just one of Razelikh's minions fall.\n\nTo break the ward placed over Razelikh's subordinates will take time and require the acquisition of rare artifacts.\n\nBe still, I must first perform the enlightenment ritual. The information I gather will assist me in forging weapons of great power.", completion = "The name of the beast must be found.", objectives = "Wait for Loramus to complete the enlightenment spell.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3509] = { id = 3509, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Name of the Beast", description = "There is only one way to harm the demon lord and his minions. A weapon of power must be forged bearing his true name.\n\nWhen such a weapon is forged, the demon and all under his command are vulnerable.\n\nA lesser deity resides in Azshara: Lord Arkkoroc. You must seek him out but be warned, his minions will stop at nothing to destroy you if you are discovered.\n\nUndoubtedly, you will have to pay a price for such information.", sourceObjective = "Speak with Lord Arkkoroc in Azshara. Begin your search at the waters edge to find the Temple of Arkkoran.", completion = "A demon lord?\n\n<Lord Arkkoroc laughs.>\n\nPerhaps the one can assist you with this information; but first, you must assist the one.", sourceObjectiveStatus = "unverified-source-field" }
quests[3510] = { id = 3510, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Name of the Beast", description = "She kills my children, mortal. She that calls herself the ruler of these oceans. A false god, nothing more. Crush her and bring back all of her heads.\n\nFor that, you will be given the name that you seek and something else of equal importance.\n\nShe roams the clutch... Hetaera she is called.\n\n<Lord Arkkoroc points to the southwest.>\n\nGo!", progress = "<Lord Arkkoroc bends down to inspect you.>\n\nWhere are they?", completion = "Finally, one worthy of the wisdom of Arkkoroc!", objectives = "Slay Hetaera and bring back Hetaera's Bloodied Head, Hetaera's Beaten Head, and Hetaera's Bruised Head to Lord Arkkoroc.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3511] = { id = 3511, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Name of the Beast", description = "As promised, I will reveal the name of the demon lord, Razelikh the Defiler. First, however, I must prepare something of utmost importance for your journey.\n\nThe weapon you seek to create requires a temper. Give me a moment to drain the blood from these heads.\n\n<Lord Arkkoroc squeezes the heads in between his gigantic fists, draining them of their blood.>\n\nTake the temper back to Loramus along with the name of the beast: Rakh'likh.", progress = "You return! Astounding, {race}. Did you discover the true name?", completion = "The temper will add the necessary vitriol we require for the forging of the weapons. There is but one more step in their creation.", objectives = "Take the temper back to Loramus Thalipedes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3512] = { id = 3512, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Eranikus' Own Words", description = "{name}, our first step will be to devise a method to speak with Eranikus through the gem.  He lies in a precarious state between sleep and death now, twisted within a weave of nightmares.  Though the essence you have given me is badly tainted, there is a chance we can reach him.\n\nTravel far to the icy lands of eastern Winterspring and seek one of our mortal allies, Umbranse the Spiritspeaker.  He is a human medium who speaks for the dead.  Though Eranikus is not truly dead, he may be of aid to us still.", completion = "Itharius was wise to send you to me.  While he is not dead as you understand death, Eranikus will soon give us advice in his own words.  For now though, I cannot directly help you... at least not yet.\n\nI will lend my skill at death-speaking to you, but first I need the help of one who - unlike me - is not limited by the frailties of old age.  My most potent augury device has been taken from me against my will, and unless I have it back we will be at a loss to help Eranikus.", objectives = "Travel to the eastern part of Winterspring and speak with Umbranse the Spiritspeaker.{name}, our first step will be to devise a method to speak with Eranikus through the gem. He lies in a precarious state between sleep and death now, twisted within a weave of nightmares. Though the essence you have given me is badly tainted, there is a chance we can reach him.\n\nTravel far to the icy lands of eastern Winterspring and seek one of our mortal allies, Umbranse the Spiritspeaker. He is a human medium who speaks for the dead. Though Eranikus is not truly dead, he may be of aid to us still.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3513] = { id = 3513, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Runed Scroll", description = "The official-looking scroll is wrapped tightly with a silvery ribbon. You're sure someone would be interested in seeing this, but who?\n\nThere is an outpost close to the Ashenvale border to the north, and if the information on this scroll involves the night elves, this would be the place to take it.", progress = "Whaddya got?", completion = "Well now... Where did you find this?", objectives = "Take the Runed Scroll to the northern guard tower in the Barrens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3514] = { id = 3514, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Horde Presence", description = "This scroll is from that scheming dryad Rynthariel, Keymaster of the Talon Den on Stonetalon Peak.\n\nShe'll not be making any more contact with the messenger you looted this from, heh, but we must stand our ground here. The Horde will not tolerate her outrunners here.\n\n{name}, travel to the Talon Den. Kill Rynthariel, and then put up a symbol for all to see. Take this Horde flag, {name}. Put it up in the Talon Den so that they will not be so rash as to send another messenger through our territory again.", completion = "You're a tough one! Ridding the Den of Rynthariel is a major step, {name}. They will be slow to regroup, and so we can count on less Alliance runners in the Barrens. They will think again before sending another this way.\n\nThank you.", objectives = "Kill the leader of the Talon Den, Rynthariel the Keymaster.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3517] = { id = 3517, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stealing Knowledge", description = "I admit, {name}, I've made the most of my situation in Azshara. Belgrom's punishment has had its share of benefits.\n\nBefore I left, I did some research and you would be surprised how many valuable items are lying around.\n\nI'll tell you more about my deals, and even give you a cut of the profits, if you help me gather some of them.\n\nThere are tablets throughout the Ruins of Eldarath to the east that I need. All four are named after Highborne wizards. Get them for me and we'll talk some more.", progress = "The tablets I'm having you gather should bring in a pretty copper or two to the right parties. I'll tell you who we need to deliver them to after you've found them. But I'm no fool... you'll get your share after I have proof that they've been delivered.\n\nSo get to it--we don't have all day. I might have to find someone else to help me.", completion = "Perfect, {name}, and in good condition also. These should get us a good price from all the parties concerned.\n\nLet's not dawdle around here any longer than we have to. We have some money to make.", objectives = "Find the Tablet of Beth'Amara, the Tablet of Jin'yael, the Tablet of Markri, and the Tablet of Sael'hai before returning to Jediga in Azshara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3518] = { id = 3518, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delivery to Magatha", description = "The first tablet goes to a tauren female... one called Magatha. She is among the elders in Thunder Bluff, and is one of the proponents of the alliance between the tauren and the Forsaken. She, more than anyone among the elders, feels the tauren and their ways can help the Forsaken find a path back to being human.\n\nBring her the Tablet of Beth'Amara. The tablet may be the link she needs in finding a way to help the Forsaken... or so she claims.", progress = "Yes, {name}. What can I do for you? I have many matters I must attend to, so please, be quick.", completion = "Ah, at long last, the Tablet of Beth'Amara. I was wondering if my partnership with Jediga had failed or if the poor orc had found her death in Azshara. I am glad she was successful.\n\nBeth'Amara was one of the Highborne's most influential alchemists. The wizard alone was said to have mastered transmuting metals among other things.", objectives = "Bring the Tablet of Beth'Amara to Magatha in Thunder Bluff.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3519] = { id = 3519, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Friend in Need", description = "Ughhh... I was bitten very badly by a spider named Githyiss the Vile while exploring the spider cave very close to here. I am sure I have been seriously poisoned; you must help me.\n\nPlease tell Dirania Silvershine. She will be able to help me.\n\nHurry... I'm so dizzy...", sourceObjective = "Speak to Dirania Silvershine in Shadowglen.", completion = "Oh dear; I was wondering why I hadn't seen Iverron yet today. And I've always warned him about those spiders...", sourceObjectiveStatus = "unverified-source-field" }
quests[3520] = { id = 3520, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Screecher Spirits", description = "I seek the spirits of the vale screechers of Feralas.  They are the cousins of an old, old god, and their spirits are linked to him.\n\nTake this bramble wand and go to Feralas.  Find and defeat vale screechers in southern and central Feralas, then wave my bramble over their fallen bodies.  This will coax their spirit to reveal itself.  Touch the spirit and collect its essence.\n\nReturn to me with my bramble and with the collected essence, and I will tell you more of the old god of which I spoke.", progress = "Have you collected the essence of the screecher spirits, {name}?", completion = "You have done well, {name}.  Perhaps now it is time to reveal more...\n\nThere is an ancient prophecy among the trolls, where the dead god Hakkar, the Soulflayer, will one day return to this earth.  Some say the coming of Hakkar will bring joy and glory to trollkind, while others believe his resurrection marks the end of all things.\n\nI do not believe this myth, but I do know the essence of Hakkar holds great power, and this power should be kept from those who would abuse it...", objectives = "Capture the spirits of 3 screechers in Feralas, then return to Yeh'kinya in Steamwheedle Port.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3521] = { id = 3521, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Iverron's Antidote", description = "I'm really worried about my friend Iverron. He's  been gone for nearly a day and I fear he may have been poisoned... or worse.\n\nI want you to gather the materials to make an antidote just in case. Gather hyacinth mushrooms from the base of the nearby trees, moonpetal lilies from around the water, and a webwood ichor from one of the spiders to the north.\n\nMixing it all together is simple enough, even if he's poisoned. He was heading north to Shadowthread Cave, hopefully you can find him near there.", progress = "Please, collect the ingredients, {name}. Iverron needs our help.", completion = "Thank Elune that you have gathered these ingredients so quickly!\n\nIn just a moment, I will have the antidote prepared.", objectives = "Collect 7 Hyacinth Mushrooms, 4 Moonpetal Lilies, and 1 Webwood Ichor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3522] = { id = 3522, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Iverron's Antidote", description = "The antidote is ready, {name}. Please see that Iverron drinks it.\n\nThere is something that you should know -- the antidote -- it will only remain viable for 5 minutes. You must get it to him in time.\n\nSpeed be with you, {name}.", progress = "Oh... {name}, I'm so glad you have returned.", completion = "What is this, {name}?\n\nOh, I knew Dirania would be able to help me!\n\n\n\nI'm always getting into trouble and Dirania, well, she always manages to help me out of it.\n\nI am feeling much better, but I think I will sit here for a while longer, until I feel completely better. Well, that, and I was hoping you'd clear a path for me through those vicious Webwood spiders...", objectives = "Bring Iverron's Antidote to Iverron before the time limit is up. Iverron can be found by the cave to the north.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3523] = { id = 3523, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scourge of the Downs", description = "Outstanding!  My name is Belnistrasz, and I thank you for rescuing me.  I had given myself up for dead... or worse, as a meal for these Scourge-infested vermin.  Yes - I said Scourge all right; they've brokered some sort of deal with the Quilboar here, and this nightmare is a result.\n\nListen... rather than just flee, I want to make a difference for all of our sakes.  Would you be up to helping me out to that end?  It's probably dangerous, but you seem to be the type not to worry about that too much.", progress = "I'm not one for politics; I care not if your affiliations are for either Horde or Alliance.  I am more interested in squelching direct and dire threats to all the races... and we have quite a large one in here.\n\nIf you're willing to be a true hero for all people, then hand me the oathstone I have given you as a sign of commitment.  I'm... not from around these parts; an oathstone is important to people of my kind as a bond of agreement.", completion = "Fantastic, I thought you looked to be the heroic type!  We've got our work cut out for us {name}, I'm not going to lie to you.  If we stay focused on the task at hand, we should be able to come out on top.\n\nNow, let me bring you up to speed on what's been going on...", objectives = "If you agree to aid Belnistrasz, speak with him again and hand the Oathstone he gave you back to him.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3524] = { id = 3524, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Washed Ashore", description = "Majestic sea creatures are known to launch themselves at the Darkshore coastline, beached there until they die. Lately, these beasts have been washing ashore in ever-increasing numbers.  I've been sent here by the Temple of the Moon to investigate, but the presence of murlocs along the water has made my research difficult.\n\nThere is a giant creature washed ashore just south of Auberdine that is ringed by the foul Greymist murlocs.  Could you go there and retrieve bones from the creature for our study?", progress = "It is only recently that these creatures started landing on the coast of Darkshore in such alarming numbers.  I can't help but think that this is an ill omen of some sort.  Recovering a sample of that creature's bones to the south would help us in Darnassus assess this situation!", completion = "I hope the murloc did not give you much trouble in collecting this for us!  I will be sure to get this on the next hippogryph to Darnassus.  The Temple of the Moon has given me some funds to hand out for assistance; please have some with our thanks.\n\nYour success here emboldens me to offer you a chance to aid the Temple of the Moon further, if you are interested...", objectives = "Recover Sea Creature Bones from the beached sea creature just south of Auberdine, and then return with it to Gwennyth Bly'Leggonde in Auberdine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3525] = { id = 3525, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Extinguishing the Idol", description = "Near the entrance is an idol that functions as a macabre oven for the Quilboar; the beasts... they literally consume their abductees from the Barrens.  I can shut down the idol and bind them from using it again, but I need your aid in doing so.  My plan: escort me to the idol.  Once we arrive, I'll commence the ritual.  I'll barely be able to communicate with you, let alone defend myself.  Protect me while I shut down the idol.  If they take me down, then it's all over for us.\n\nAre you with me?!", completion = "Belnistrasz's sudden departure has left behind a burning brazier.  As you stare in to the flame, the image of a great-winged red dragon fills your mind.  A more graveled version of Belnistrasz's voice speaks directly to you.\n\n\"Indeed mortals, you are the heroes I had hoped you would be.  Thanks to you the butchery these beasts were perpetrating is a thing of the past.  My faith in mortals such as yourself has been once more renewed.  Take this as a reward befitting of a hero.\"", objectives = "Escort Belnistrasz to the Quilboar's idol in Razorfen Downs.\n\nProtect Belnistrasz while he performs the ritual to shut down the idol.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3526] = { id = 3526, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goblin Engineering", description = "Expert engineering yields two distinct disciplines: gnome and goblin.  Clearly, goblin engineering is the choice of all brilliant engineers.  Learn to master the world through the judicious use of high explosives and fantastic gear!\n\n{name}, read this manual.  If you want to learn about goblin engineering, then take it to Nixx Sprocketspring in Gadgetzan.   Remember - membership is permanent and prevents joining the other discipline, so make sure this is what you want before finishing his task.", progress = "I can smell fresh recruits much like I can an excellent blasting powder - from a mile away. Have you come seeking to learn about the mastery of the explosion?", completion = "Well {name}, you were wise to seek my tutelage! Any schlep can become an expert at the basics of engineering - the gnomes and their irradiated home of Gnomeregan are proof of that. It takes a strong mind and a steady hand (emphasis on STEADY) though to master the discipline of Goblin Engineering.\n\nKeep your ears perked {name}, and you might learn something.", objectives = "If you wish to learn more about Goblin Engineering, take the Manual of Engineering Disciplines to Nixx Sprocketspring in Gadgetzan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3527] = { id = 3527, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Prophecy of Mosh'aru", description = "The ancient prophecy of Mosh'aru speaks of a way to contain the god Hakkar's essence.  It was written on two tablets and taken to the troll city of Zul'Farrak, west of Gadgetzan.\n\nBring me the Mosh'aru tablets!\n\nThe first tablet is held by the long-dead troll Theka the Martyr.  It is said his persecutors were cursed into scarabs and now scuttle about his shrine.\n\nThe second tablet is held by the hydromancer Velratha, near the sacred pool of Gahz'rilla.\n\nWhen you have the tablets, bring them to me.", progress = "Do you have the tablets of the Prophecy of Mosh'aru, {name}?\n\nWhen I gain the tablets, I will study them, and learn how to contain the essence of Hakkar!", completion = "Ah, this is good.  I can fuse these ancient tablets together, and then study their hidden secrets.\n\nMy debt to you grows, {name}.  And it will grow further still.", objectives = "Bring the First and Second Mosh'aru Tablets to Yeh'kinya in Tanaris.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3528] = { id = 3528, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The God Hakkar", description = "Now it is time to capture the essence of the avatar of Hakkar.\n\nTake the Egg of Hakkar to the Sanctum of the Fallen God in the Sunken Temple in Azeroth.  Invoke the egg's power to stir the dead god.\n\nHe will send his minions against you.  Defeat his bloodrinkers and take their Hakkari blood, then use the blood to dowse the eternal flames that hold Hakkar's spirit.  When all the flames go out, the avatar of Hakkar will enter our world.\n\nDefeat him, and place his essence within the Egg of Hakkar.", progress = "Have you defeated the avatar of Hakkar, {name}?  Has his essence yet empowered the egg I gave you?", completion = "The essence of Hakkar has been collected!  Even now the Egg stirs with life!  Could the myths of Hakkar be true?\n\nThat must not be true, for it is then I fear what Hakkar may do if birthed again.  I will keep this egg safe and be sure it does not fall into evil hands.\n\nYour labors with me are finished, {name}.  You have touched a legend, and your actions may one day change the face of our world.", objectives = "Bring the Filled Egg of Hakkar to Yeh'kinya in Tanaris.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3541] = { id = 3541, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delivery to Jes'rimon", description = "I have a fence in Orgrimmar. He resides in The Drag. He's difficult to nail down if you don't know where to look, but if you go looking in one of the highest buildings there you should have no problem finding him.\n\nDo me a favor though, don't go shouting to all of Kalimdor that he's there and what his business is--it'd be bad for both of us.\n\nHe'll give us more than a fair price for the Tablet of Jin'yael. I'm not sure why, but you should have seen how excited he was to hear about its whereabouts.", progress = "Yes, what you be needin', mon? I got many tings to be takin' care of today, and you not be on me agenda as one of them. Pester me, and I make sure that changes.", completion = "Ahhh, Jediga be sendin' her package all the way from Azshara. Good. I be waitin' on this.\n\nJediga, now that be a fine woman... deadly too. What could be better?\n\nLook at this... the tablet be in perfect condition. You make a good messenger, {name}.", objectives = "Bring the Tablet of Jin'yael to Jes'rimon in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3542] = { id = 3542, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delivery to Andron Gant", description = "Andron Gant is my next contact. He usually holds himself up in the Undercity... right near the Apothecarium.\n\nHe was a little more loose-lipped when it came to speaking about what he wanted the Tablet for. Apparently some of the mages of Undercity are looking to study some of the arcane spells the highborne used. They think this tablet will help them. Markri was adept at summoning creatures; especially elementals.\n\nTake the Tablet of Markri and return to me for your part of the reward.", progress = "Well... <hic>... isn't this a surprise? An adventurererere... <hic>!\n\nWhat c'n I do for you... <hic>?", completion = "Here, take some coin... get yerself... <hic>... some new armor or something....\n\nThis'll bring a shiny gold or two to the right... <hic> people.", objectives = "Bring the Tablet of Markri to Andron Gant in Undercity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3561] = { id = 3561, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delivery to Archmage Xylem", description = "This final tablet goes to someone very dangerous, {name}. Heed me when I tell you that I trust this person far less than anyone else I've asked you to meet with.\n\nArchmage Xylem has a tower up in the hills overlooking Azshara. He's human, but he acts like no human I've met... or killed. He exudes power, and I dare not ask him what he plans on doing with the tablet.\n\nHe came to me, but told me that his bodyguard Sanath would help me get to the tower when I was ready to meet him. Look north for Sanath.", progress = "What can I help you with, {name}?", completion = "Ah, the Tablet of Sael'hai... how long I've longed to study it.\n\nThank you, {name}. You may tell Jediga that she has done well. This will definitely be worth the payment she asked for.", objectives = "Bring the Tablet of Sael'hai to Archmage Xylem in Azshara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3562] = { id = 3562, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magatha's Payment to Jediga", description = "Take this note to Jediga. Tell her the payment will be here for her when she returns. And tell her I am pleased with her work.\n\nGo swiftly, {name}. Tell your master I will be awaiting her here.", progress = "Well, what did Magatha say? The old crone... I bet she was less than polite.", completion = "Ah, good. She was much more reasonable than I expected... at least towards you. I half expected her to have you punished for my insolence in sending someone in my place. She must really want that tablet. Interesting.\n\nSomething to ponder another time.", objectives = "Deliver Magatha's Note to Jediga in Azshara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3563] = { id = 3563, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jes'rimon's Payment to Jediga", description = "Take this letter to Jediga. Let her know that our deal has been beneficial and I be pleased with her work.\n\nYou tell her she come back to Orgrimmar fast and Jes'rimon make sure he take good care of her.\n\nTell her that, and maybe in the future I have need of your services again, {name}.", progress = "Have you spoken to Jes'rimon yet?\n\nHe's a boar among trolls, but his information is usually accurate and his jobs well paying.\n\nIf you can stand his attitude then you stand to make some good coin from his business endeavors.", completion = "I can see he was more than pleased by the looks of his note.... a little too pleased.\n\nPerhaps some day I'll take time to make sure he knows how much I appreciate his advances also. Well, at least there's one reason to look forward to spending more time in Azshara.\n\nHere's your share of our payment.", objectives = "Deliver Jes'rimon's Note to Jediga in Azshara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3564] = { id = 3564, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Andron's Payment to Jediga", description = "Here... take... <hic> this to Jediga. Good luck to ya!", progress = "Have you met with Andron yet? He rarely leaves Undercity, so I don't think it'd be too hard to find him.", completion = "Perfect... wait a minute.\n\nHaha! What'd you tell him when you delivered the tablet, {name}? He overpaid us way too much! Not that I'm complaining. Did you tell him the deal changed? Or was he drunk again?\n\nDoesn't matter... here, take an extra share also.", objectives = "Deliver Andron's Note to Jediga in Azshara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3565] = { id = 3565, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Xylem's Payment to Jediga", description = "What is it? Oh yes, your payment. Of course.\n\nTake this and be off with you. I'm sure Jediga is awaiting oh so patiently for your return.", progress = "Well, what did Xylem have to say? He didn't do anything to you, did he? Cast a spell on you? Con you into doing work for him?", completion = "No problems? None at all? Well, that's something to be said... I expected him to show some sort of reluctance or to at least betray our deal. Hmm, maybe he can be trusted after all.\n\nWell, no need to dwell on it that much. Here's your share. Thank you for your help.", objectives = "Deliver Xylem's Note to Jediga in Azshara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3566] = { id = 3566, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rise, Obsidion!", description = "It... It... It was all a trap.\n\nForgive... me.\n\nKill the traitor... Kill him for us... for Thorius.", progress = "I don't believe you! Show me proof!", completion = "<Thorius' face turns white.>\n\nThis... this cannot be. My own brother? He set this all up?\n\n<Thorius' face contorts in anger.>\n\nHe betrayed me, he betrayed Ironforge! It seems as if the influence of the Old Gods is still strong in these lands. I fear that if my brother - a once noble and honorable man - was so easily turned to the will of Ragnaros, no one is safe.", objectives = "Slay Lathoric the Black and Obsidion, and return to Thorius in Ironforge with the Head of Lathoric the Black and the Heart of Obsidion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3567] = { id = 3567, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Top", objectives = "Would you like to see the view atop one of the twin colossals? I can send you there, {race}.\n\nDo consider how you will get down, though. This is a one way trip only.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3568] = { id = 3568, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeping Corruption", description = "See that tauren behind me--the one who looks like she's going to be ill at any moment? She was in Azshara recently. She claims she was wounded by some naga while making her way through the Ruins of Eldarath.\n\nAfter fighting off a few of them, she took a break on the beach and drank from one of the tide pools. Now she's feeling nauseous... among other things.\n\nI'd like to find out what she drank. Take this box, in it are some empty vials I labeled. Fill each at different pools and come back.", progress = "You know where this is leading, don't you, {name}? There's no way she can survive... look at her. The best thing for her now is to aid us in finding a cure for the plague. This water she drank might have a clue that helps us figure out how. She's going to die anyway--she might as well die doing something noble for our people before she does. Don't you agree?", completion = "Wonderful. You're back before she died. Good, good.\n\nLet's get started on this then, shall we?\n\nI've been studying her symptoms for some time now, and it's quite ugly. I'm surprised she's still standing. She's vomited three or four times all over the place... quite a pleasant odor.\n\nGive me just a moment to put something together to test on our... friend.", objectives = "Fill all 4 Empty Vials at the tide pools along the coast of the Ruins of Eldarath in Azshara before returning to Chemist Cuely.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3569] = { id = 3569, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeping Corruption", description = "Give this to Thersa. Perhaps it will cure her... perhaps not. We really won't know until after she drinks it.", progress = "I've come to Undercity because I heard their alchemists have been studying long and hard on how to find a cure for their own illness. It was suggested that perhaps they could help me too.\n\nAlthough this place makes me feel far from welcome, I had no choice--the sickness that found me is tearing me up inside and I needed their help immediately.", completion = "Chemist Cuely has been very accommodating... disturbingly so. But if he says this will help me, then I have no other choice. I don't have time to find any other solution. I've already spoken to priests and shamans, none of which could help me.\n\nLet us hope that the Earthmother watches over my spirit.", objectives = "Give Cuely's Elixir to Thersa Windsong in Undercity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3570] = { id = 3570, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeping Corruption", sourceObjective = "I never dreamed the elixir would take hold that quickly. Thank you, {name}. I will get to work on the rest of these samples right away. I'm sure they'll be usable by the Lady Sylvanas and the Forsaken soon enough.", sourceObjectiveStatus = "unverified-source-field" }
quests[3601] = { id = 3601, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kim'jael Indeed!", description = "Kim'jael indeed!! Do you know what Kim'jael means to the Blood elves, {name}? Little rat... or something like that. The big bullies!\n\nThey hired me to help them scout the area looking for some sort of lost treasures. Of course I jumped aboard the moment they said \"treasure\" and the amount they were willing to pay, but of course, they turned on me and tried to kill me... ME!\n\nGoes to show you, you can't trust a Blood elf.\n\nThe problem is, they still have my equipment and I can't get it back. Help me out?", progress = "Those stinkin' Blood elves. I tell ya, if I was as strong as you are, I'd go down there and teach them a thing or two myself! But I'll have to settle with payin' you to take care of 'em for me.", completion = "Haha! You got them good, didn't you?!\n\nThis is great! That'll teach those Blood elves to betray their partners... especially someone as loyal as a goblin merchant! Bah, Blood elves...!\n\nWell, the least I can do for you is pay you for your time... just like I said I would.\n\nHere you go... those should be useful.", objectives = "Search the Thalassian Base Camp for Kim'jael's Compass, Scope, Stuffed Chicken and Wizzlegoober, then return them to him in Azshara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3602] = { id = 3602, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azsharite", description = "The ancient cliff giants of the southern region of Azshara consume the rock and buildings of the land for sustenance. The excrement from their consumption is a highly malleable and extremely strong crystal known as Azsharite.\n\nThe formations litter the southern arc, but few are ever recovered due to the extremely violent nature of the giants.\n\nYou are to venture south and recover enough of the Azsharite for the creation of the weapon's body. My felhounds will aid in the recovery of the crystal.", progress = "Evil does not sleep, fool. You will have time for rest when you are finally dead. Now, bring me those crystals.", completion = "Your tasks in Azshara are complete, mortal. I must now forge the necessary components for the next step in your adventure.", objectives = "Recover twenty Crystallized Azsharite from southern Azshara. You may use the Felhound to assist you in 'sniffing' out the location of cleverly hidden deposits.\n\nReturn to Loramus when the task is complete.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3621] = { id = 3621, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Formation of Felbane", description = "The weapons are ready to be forged. You must take the tempered azsharite to one with the ability to harness fel energy.\n\nIn Stranglethorn Vale such a blacksmith exists. Galvan the Ancient, leader of the Mithril Order, will craft the weapons to your specifications. You will find his encampment between Zul'Gurub and the Mosh'Ogg ogre mound.\n\nMay your determination and faith carry you through this ordeal. Should you fail, know that your God smiles down upon you, mortal.", progress = "Loramus, eh? It has been many years since I have heard that name.", completion = "My goodness, I can only imagine what you went through to get these materials. Few venture into Azshara and return alive, let alone those that face demi-gods and giants!", objectives = "Take the Shipment to Galvan the Ancient in Stranglethorn Vale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3625] = { id = 3625, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enchanted Azsharite Fel Weaponry", description = "{name}, the creation of each weapon will take some time.\n\nAdditionally, you may only use the power of the Felcurse once per three minutes. Its weakening properties against Razelikh the Defiler and his minions may be variable in duration. This is why you must release the Felcurse only when the moment is right!\n\nNow give me a moment to craft your weapon, {name}.", completion = "<Galvan wipes the sweat from his brow.>\n\nA finer demon slayer has never existed, {name}.", objectives = "Wait for Galvan to finish forging the weaponry.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3626] = { id = 3626, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the Blasted Lands", description = "The hour of redemption is near, {name}. You must return to the Blasted Lands with your new-found weaponry and speak with the Fallen Hero of the Horde to receive your final objective.", completion = "You look battle hardened, {name}. Are you prepared to face Razelikh and his minions?", objectives = "Return to the Fallen Hero of the Horde at Splinterspear Junction in Swamp of Sorrows.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3627] = { id = 3627, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uniting the Shattered Amulet", description = "To reach the Defiler, you must first destroy the triad of power and recover the amulet pieces. When you recover all three pieces, return to me and I shall give you further instruction.\n\nGo {name}! To the Blasted Lands! Sevine, Allistarj, and Grol must fall!", progress = "The three shall form the one, the one shall light the way.", completion = "The amulet of Razelikh the Defiler is once again complete but he senses the disruption in his chain of command. He knows you come for him...", objectives = "Slay Grol the Destroyer, Lady Sevine, and Archmage Allistarj. From their corpses take the Amulet of Grol, the Amulet of Sevine, and the Amulet of Allistarj.\n\nRemember to USE your Enchanted Azsharite Fel Weaponry to weaken the triad. They cannot be killed otherwise - but use them wisely...", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3628] = { id = 3628, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You Are Rakh'likh, Demon", description = "Razelikh's lair is atop the highest mountain in the Blasted Lands. The only way to the lair is through the use of the teleport runes near the mountain. As long as you hold the amulet, you can freely transport up to the lair. Once you reach the lair, you must conjure the beast. The amulet is your key, {name}. Use it on the Altar of the Defiler.\n\nShould you defeat the Defiler, bring back his horn. It will become a symbol of hope for all that view it - proof that heroes do exist in this war torn world.", progress = "There is nothing left to fear.", completion = "Today is a day that will be remembered for all eternity. The demonic overlord of the Blasted Lands has finally fallen!", objectives = "Destroy Razelikh the Defiler and return the Severed Horn of the Defiler to the Fallen Hero of the Horde. You will also need to return the Ward of the Defiler so that the Fallen Hero can destroy it, preventing it from ever falling into the wrong hands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3629] = { id = 3629, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goblin Engineering", description = "Expert engineering yields two distinct disciplines: gnome and goblin.  I only bother to mention goblin engineering because I'm a fair trainer.  They like to make things that blow up, and they rarely care what is in the way - even themselves.\n\n{name}, read this manual.  If you want to learn how to blow yourself up, then take it to Nixx Sprocketspring in Gadgetzan.   Remember - membership is permanent and prevents joining the other discipline, so make sure this is what you want before finishing his task.", progress = "I can smell fresh recruits much like I can an excellent blasting powder - from a mile away. Have you come seeking to learn about the mastery of the explosion?", completion = "Well {name}, you were wise to seek my tutelage! Any schlep can become an expert at the basics of \tengineering - the gnomes and their irradiated home of Gnomeregan are proof of that. It takes a strong mind and a steady hand (emphasis on STEADY) though to master the discipline of Goblin Engineering.\n\nKeep your ears perked {name}, and you might learn something.", objectives = "If you wish to learn more about Goblin Engineering, take the Manual of Engineering Disciplines to Nixx Sprocketspring in Gadgetzan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3630] = { id = 3630, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnome Engineering", description = "Engineering at the expert level breaks into two disciplines: gnome and goblin.  Gnome engineering represents by far the superior of the two!  It's about the construction of wonderful gadgets and devices that make life better!\n\n{name}, read this manual.  If you want to learn more on gnome engineering, then take that manual to Tinkmaster Overspark in Ironforge.   Remember - membership is permanent and prevents joining the other discipline, so make sure you are sure before finishing his task!", progress = "Yes, yes, what needs of yours might I address today?  Clearly, I have the time to do such since all I do is stand here while our beloved city lies in a cloud of irradiated death.", completion = "Ah, a young engineer interested in pursuing the one, true discipline of engineering!  Well forgive my melodrama, friend.  While our situation remains dire, it still is always a good day to see another engineer respond to the clarion call of true engineering!", objectives = "If you wish to learn more about Gnome Engineering, take the Manual of Engineering Disciplines to Tinkmaster Overspark in Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3631] = { id = 3631, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Summon Felsteed", description = "Hmph. I say you're not prepared, but that is not my decision. Strahad feels otherwise, and it is his decision to make... this time.\n\nHe wishes to speak to you, and quickly. You'll find him still above Ratchet in the Barrens, at his little tower there with his acolytes.\n\nDo not dawdle long.", sourceObjective = "Speak to Strahad Farsan in the Barrens.", sourceObjectiveStatus = "unverified-source-field" }
quests[3632] = { id = 3632, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnome Engineering", description = "Engineering at the expert level breaks into two disciplines: gnome and goblin.  Gnome engineering represents by far the superior of the two!  It's about the construction of wonderful gadgets and devices that make life better!\n\n{name}, read this manual.  If you want to learn more on gnome engineering, then take that manual to Tinkmaster Overspark here in Ironforge.   Remember - membership is permanent and prevents joining the other discipline, so make sure you are sure before finishing his task!", progress = "Yes, yes, what needs of yours might I address today?  Clearly, I have the time to do such since all I do is stand here while our beloved city lies in a cloud of irradiated death.", completion = "Ah, a young engineer interested in pursuing the one, true discipline of engineering!  Well forgive my melodrama, friend.  While our situation remains dire, it still is always a good day to see another engineer respond to the clarion call of true engineering!", objectives = "If you wish to learn more about Gnome Engineering, take the Manual of Engineering Disciplines to Tinkmaster Overspark in Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3633] = { id = 3633, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goblin Engineering", description = "Expert engineering yields two distinct disciplines: gnome and goblin.  Clearly, goblin engineering is the choice of all brilliant engineers.  Learn to master the world through the judicious use of high explosives and fantastic gear!\n\n{name}, read this manual.  If you want to learn about goblin engineering, then take it to Nixx Sprocketspring in Gadgetzan.   Remember - membership is permanent and prevents joining the other discipline, so make sure this is what you want before finishing his task.", progress = "I can smell fresh recruits much like I can an excellent blasting powder - from a mile away. Have you come seeking to learn about the mastery of the explosion?", completion = "Well {name}, you were wise to seek my tutelage! Any schlep can become an expert at the basics of engineering - the gnomes and their irradiated home of Gnomeregan are proof of that. It takes a strong mind and a steady hand (emphasis on STEADY) though to master the discipline of Goblin Engineering.\n\nKeep your ears perked {name}, and you might learn something.", objectives = "If you wish to learn more about Goblin Engineering, take the Manual of Engineering Disciplines to Nixx Sprocketspring in Gadgetzan in Tanaris.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3634] = { id = 3634, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnome Engineering", description = "Engineering at the expert level breaks into two disciplines: gnome and goblin.  While I think it is a waste, you should be aware of gnome specialization.  They make items and gadgets that claim to change the world, but rarely often work.\n\n{name}, read this manual.  If you wish to learn how to make metal paper weights, then take that manual to Tinkmaster Overspark in Ironforge.   Remember - membership is permanent and prevents joining the other discipline, so make sure you are sure before finishing his task!", objectives = "If you wish to learn more about Gnome Engineering, take the Manual of Engineering Disciplines to Tinkmaster Overspark in Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3635] = { id = 3635, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnome Engineering", description = "Engineering at the expert level breaks into two disciplines: gnome and goblin.  While I think it is a waste, you should be aware of gnome specialization.  They make items and gadgets that claim to change the world, but rarely work.\n\n{name}, read this manual.  If you wish to learn how to make metal paper weights, then take the manual to Oglethorpe Obnoticus in Booty Bay.   Remember - membership is permanent and prevents joining the other discipline, so make sure you are sure before finishing his task.", progress = "Hello there! If you've come about a homing robot that may have smashed through a wall of your domicile, then I will refer you to my barrister in advance. Otherwise, what can I do for you today?", completion = "You've come to learn about gnome engineering, eh? Well, you've come to the right gnome. While the ruling faction of Gnomeregan may use politics to ostracize those they view as an intellectual threat, they know that knowledge is something they cannot control.\n\nThey and I both know that when I left Gnomeregan, they lost one of their greatest gnome engineers alive today. If you're a capable student, I'll teach you what I know.", objectives = "If you wish to learn more about Gnome Engineering, take the Manual of Engineering Disciplines to Oglethorpe Obnoticus in Booty Bay.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3636] = { id = 3636, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bring the Light", description = "The Scourge is a persistent threat to the Alliance, a fact I am sure you know quite well. Recently, we have come across some very peculiar findings, {name}.\n\nIn the Barrens lies a horrid tangle of briars called Razorfen Downs. While once it was the home of simple quilboar, now it has become apparent that a pact was made with the Scourge, creating creatures far worse... They are now ruled by the lich, Amnennar the Coldbringer.\n\nAlign yourself with the Light, {name}; put an end to this evil union.", completion = "Thank you , {name}. The Scourge will now think twice before attempting to bolster its ranks again.\n\nMay you be blessed by the Light.", objectives = "Archbishop Bendictus wants you to slay Amnennar the Coldbringer in Razorfen Downs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3637] = { id = 3637, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnome Engineering", description = "Engineering at the expert level breaks into two disciplines: gnome and goblin.  While I think it is a waste, you should be aware of gnome specialization.  They make items and gadgets that claim to change the world, but rarely work.\n\n{name}, read this manual.  If you wish to learn how to make metal paper weights, then take the manual to Oglethorpe Obnoticus in Booty Bay.   Remember - membership is permanent and prevents joining the other discipline, so make sure you are sure before finishing his task.", progress = "Hello there! If you've come about a homing robot that may have smashed through a wall of your domicile, then I will refer you to my barrister in advance. Otherwise, what can I do for you today?", completion = "You've come to learn about gnome engineering, eh? Well, you've come to the right gnome. While the ruling faction of Gnomeregan may use politics to ostracize those they view as an intellectual threat, they know that knowledge is something they cannot control.\n\nThey and I both know that when I left Gnomeregan, they lost one of their greatest gnome engineers alive today. If you're a capable student, I'll teach you what I know.", objectives = "If you wish to learn more about Gnome Engineering, take the Manual of Engineering Disciplines to Oglethorpe Obnoticus in Booty Bay.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3638] = { id = 3638, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Pledge of Secrecy", description = "Goblin engineering is about practical uses for high profit and higher explosive power!  Our schemata allow us to make powerful bombs and mighty weaponry; the manual you read covered this.\n\nThe manual also covered our ages old oath of secrecy on our schemata.  Once you become a goblin engineer, that's that.  There is no access to gnome engineering at all.\n\nIf you still want to become a goblin engineer, sign this document pledging life-long secrecy and speak with me again.  Think about it carefully, {name}.", progress = "If you've signed the document and are ready to hand it to me, then that is that.  You've been told that this is a one way trip.  If you're ready, then hop on board!", completion = "Welcome aboard, Goblin Engineer {name}!  You soon will have access to the most powerful engineering schemata anywhere on Azeroth.\n\nNow that you have committed yourself to the pursuit of this knowledge, it is time to examine your goblin-oriented engineering work.  From there, we'll help you build a plan to maximize your goblin engineering talents!", objectives = "If you agree to become a Goblin Engineer, then right-click on the Pledge of Secrecy and speak once more with Nixx Sprocketspring in Gadgetzan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3639] = { id = 3639, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Show Your Work", description = "The gleam in your eye tells me everything; you want to blow things up.  You have budding talent, {name}, but I'd like to get some samples of your work so I might examine it for ways to emphasize goblin-oriented techniques.  I'll need the following: twenty big iron bombs, twenty sticks of solid dynamite, and five explosive sheep - and keep the safeties armed!\n\nSubmit these items to me and you'll be an official goblin engineer!", progress = "Once I receive your crafted engineering items for my review, I will grant you the last bit of knowledge required to join our exclusive little club, the goblin engineers!", completion = "It appears you are indeed ready for proper training.  I dub you Goblin Engineer {name}!\n\nYou'll be able to access any Goblin Engineer for some diabolical creations.  Have fun and try not to blow your face off.", objectives = "Bring 20 Big Iron Bombs, 20 Solid Dynamite, and 5 Explosive Sheep to Nixx Sprocketspring in Gadgetzan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3640] = { id = 3640, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Pledge of Secrecy", description = "Gnome engineering is about engineering theory shaped to serve our needs!  Our schemata allow us to make devices that control the world around us; the manual you read covered this.\n\nThe manual also covered our ages old oath of secrecy on our schemata.  Once you become a gnome engineer, that's that.  There is no access to goblin engineering at all.\n\nIf you still want to become a gnome engineer, sign this document pledging life-long secrecy and speak with me again.  Think about it carefully, {name}.", progress = "If you've signed the document and are ready to hand it to me, then that is that.\n\nThe secrets I will share with you are of such a magnitude that the signing of the Pledge of Secrecy is absolutely critical.  I signed one, as did my brother and sister gnome engineers.  You will be joining quite the auspicious fold, Engineer {name}!", completion = "Welcome aboard, {name}!  You soon will have access to the most advanced engineering schemata anywhere on Azeroth.\n\nNow that you have committed yourself to the pursuit of this knowledge, it is time to examine your gnome-oriented engineering work.  From there, we'll help you build a plan to maximize your gnome engineering talents!", objectives = "If you agree to become a Gnome Engineer, then right-click on the Pledge of Secrecy and speak once more with Tinkmaster Overspark in Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3641] = { id = 3641, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Show Your Work", description = "If you're ready to make some truly fantastic devices, then you've come to the right place.  And I can see you're a skilled engineer, but I want some samples of your work.  What I hope to do though is to analyze your craftmanship for ways to emphasize gnome-oriented techniques in your future efforts.  I need the following samples: six mithril tubes, an accurate scope, and two advanced target dummies.\n\nSubmit these items to me and you'll be an official gnomish engineer with access to all the schematics!", progress = "Once I receive your crafted engineering items for my review, you can become a certified gnomish engineer, granting you unlimited access to any gnome engineer trainer anywhere in the world.", completion = "Today is the day you become a real engineer, {name}.  Don't worry about all those messy bombs and explosives, because it's time to shine!", objectives = "Bring 6 Mithril Tubes, an Accurate Scope, and 2 Advanced Target Dummies to Tinkmaster Overspark in Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3642] = { id = 3642, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Pledge of Secrecy", description = "Gnome engineering is about engineering theory shaped to serve our needs!  Our schemata allow us to make devices that control the world around us; the manual you read covered this.\n\nThe manual also covered our ages old oath of secrecy on our schemata.  Once you become a gnome engineer, that's that.  There is no access to goblin engineering at all.\n\nIf you still want to become a gnome engineer, sign this document pledging life-long secrecy and speak with me again.  Think about it carefully, {name}.", progress = "If you've signed the document and are ready to hand it to me, then that is that.\n\nWhile I may vehemently disagree with Gnomeregan - especially that fool Tinkmaster Overspark - politically, the Pledge of Secrecy transcends everything else!  You must agree to commit a single path and stay true to that path throughout your life.", completion = "Welcome aboard, {name}!  You soon will have access to the most advanced engineering schemata anywhere on Azeroth.\n\nNow that you have committed yourself to the pursuit of this knowledge, it is time to examine your gnome-oriented engineering work.  From there, we'll help you build a plan to maximize your gnome engineering talents!", objectives = "If you agree to become a Gnome Engineer, then right-click on the Pledge of Secrecy and speak once more with Oglethrope Obnoticus in Booty bay.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3643] = { id = 3643, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Show Your Work", description = "If you're ready to make some truly fantastic devices, then you've come to the right place.  And I can see you're a skilled engineer, but I want some samples of your work.  What I hope to do though is to analyze your craftmanship for ways to emphasize gnome-oriented techniques in your future efforts.  I need the following samples: six mithril tubes, an accurate scope, and two advanced target dummies.\n\nSubmit these items to me and you'll be an official gnomish engineer with access to all the schematics!", progress = "Once I receive your crafted engineering items for my review, you can become a certified gnomish engineer, granting you unlimited access to any gnome engineer trainer anywhere in the world.", completion = "Today is the day you become a real engineer, {name}.  Don't worry about all those messy bombs and explosives, because it's time to shine!", objectives = "Bring 6 Mithril Tubes, an Accurate Scope, and a 2 Advanced Target Dummies to Oglethorpe Obnoticus in Booty Bay.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3644] = { id = 3644, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Membership Card Renewal", progress = "In order to renew your membership card, you will need to pay the renewal fee of two gold pieces.", completion = "Since you're a practitioner of goblin engineering and are in good standing, I am able to renew a lapsed membership card for the fee of two gold pieces.  Once this fee is paid, you will be reissued a new membership card.  This will allow access to goblin engineering schemata from appropriate trainers.\n\nThis card will last for two weeks of activity, at the end of which your membership fees will become due again!  If you want to access schemata, you'll need to bring your dues out of arrears." }
quests[3645] = { id = 3645, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Membership Card Renewal", progress = "In order to renew your membership card, you will need to pay the renewal fee of two gold pieces.", completion = "Since you're a practitioner of gnome engineering and are in good standing, I am able to renew a lapsed membership card for the fee of two gold pieces.  Once this fee is paid, you will be reissued a new membership card.  This will allow access to gnome engineering schemata from appropriate trainers.\n\nThis card will last for two weeks of activity, at the end of which your membership fees will become due again!  If you want to access schemata, you'll need to bring your dues out of arrears." }
quests[3646] = { id = 3646, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Membership Card Renewal", progress = "In order to renew your membership card, you will need to pay the renewal fee of two gold pieces.", completion = "Since you're a practitioner of goblin engineering and are in good standing, I am able to renew a lapsed membership card for the fee of two gold pieces.  Once this fee is paid, you will be reissued a new membership card.  This will allow access to goblin engineering schemata from appropriate trainers.\n\nThis card will last for two weeks of activity, at the end of which your membership fees will become due again!  If you want to access schemata, you'll need to bring your dues out of arrears." }
quests[3647] = { id = 3647, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Membership Card Renewal", progress = "In order to renew your membership card, you will need to pay the renewal fee of two gold pieces.", completion = "Since you're a practitioner of gnome engineering and are in good standing, I am able to renew a lapsed membership card for the fee of two gold pieces.  Once this fee is paid, you will be reissued a new membership card.  This will allow access to gnome engineering schemata from appropriate trainers.\n\nThis card will last for two weeks of activity, at the end of which your membership fees will become due again!  If you want to access schemata, you'll need to bring your dues out of arrears." }
quests[3661] = { id = 3661, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Favored of Elune?", description = "Wildkin are quite unpredictable creatures, {name}. Capable of incredible gentleness, these creatures will show extreme ferocity if something they deem important is threatened.\n\nThese beasts are rumored to have been created by Elune, and I am interested in finding if this is really the truth.\n\nRecently, I heard about a population of wildkin living in the Hinterlands -- Vicious, Primitive, and Savage Owlbeasts. They can be found amongst the wildlife there. Will you gather some wildkin feathers for me?", progress = "Try to avoid them if you can, {name}. The Wildkin may misread your interest as an intent to do them harm...", completion = "Thank you for bringing these to me, {name}.\n\nWhat did you learn of the Wildkin?\n\nPerhaps these feathers will tell us more. Ferocious monsters, or simply misguided pets? One day I'd like to know the truth...\n\nI am going to continue my research -- please come back and talk to me again after some time has passed.", objectives = "Collect 15 Wildkin Feathers from the Hinterlands for Erelas Ambersky in Rut'theran Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3681] = { id = 3681, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tome of Divinity", description = "Sorry to interrupt your travels, {race}, but I thought you should know that word was sent from Stormwind recently asking that paladins report there for training.\n\nIf I didn't know any better, I'd say your close to reaching a special time and it's time you started studying the Tomes.\n\nLook for Duthorian Rall in Stormwind. He usually trains paladins in the Cathedral of Light.", sourceObjective = "Speak with Duthorian Rall in Stormwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[3701] = { id = 3701, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Smoldering Ruins of Thaurissan", description = "Venture to the smoldering ruins of Thaurissan in the Burning Steppes and gather as much information as possible.\n\nIt is said that mysterious relics litter the ruins. Perhaps you should start your search there, {name}. Beware the Thaurissan guardians: Assassins that guard the ruins, keeping whatever secrets may still be buried there protected.", completion = "Oh my! This information explains quite a lot about Thaurissan.\n\nThere is much more to learn!", objectives = "Venture to the Ruins of Thaurissan in the Burning Steppes and recover information from the Thaurissan Relics. Return to Royal Historian Archesonus when you have recovered the information.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3702] = { id = 3702, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Smoldering Ruins of Thaurissan", description = "Would you like to hear a brief history of the Dark Iron dwarves?", completion = "Shall we proceed?", objectives = "Listen to Royal Historian Archesonus recant the history of Thaurissan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3721] = { id = 3721, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An OOX of Your Own", objectives = "You've recovered three of my OOX homing robots!  You've gone above and beyond what you needed to, so I will give you something special for all your help.  It is a miniature version of the very same robot that you have come to know and love, the OOX!\n\nI normally wouldn't let anyone have such a potentially lethal device, but you've been a real help.  Besides - the combat mechanisms and the homing logic on this one have been disabled.\n\nOther than that, it's an OOX by golly!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3741] = { id = 3741, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilary's Necklace", description = "My friend Hilary lost her necklace, and we can't find it.  We've been fishing all day right here, and we looked around here already.  The only thing I can think of is that it fell into the lake.  Our parents don't want us to swim in the lake... my mom says there's some mean things underwater, but you look like you aren't scared of mean things.\n\nCould you find it for her, please?", progress = "Hi.  I miss my necklace.  My daddy got it for me.  Daddy says that there are monsters in the lake.  Did you beat up any monsters?", completion = "Thank you for finding my necklace mister {class}... you are very kind!  My kitty thanks you too - isn't that right Effsee?", objectives = "Find Hilary's Necklace, and return it to Hilary in Lakeshire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3761] = { id = 3761, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Un'Goro Soil", description = "The soil of Un'Goro Crater is reportedly enriched with potent magical qualities.  The Cenarion Circle wants to study this soil in large quantities; go into the wilds of Un'Goro and acquire enough of it for our continued research.\n\nThe rich soil will stick out in piles from time to time, and some of the beasts might have usable samples on their being.  Take them all outside to Ghede; just look for the piles of dirt and the tauren barking orders.  He means well, just don't get him riled up though!", progress = "At ease, Private.  If you're here to unload soil from Un'Goro - outstanding then!  Otherwise, disappear.", completion = "Oh that's right Private {name}, don't make any effort to help me unload this soil up on to the piles!  If the Great Spirits had wanted it done they would have miracled it up there, now wouldn't they?!\n\nArch Druid Runetotem wants to speak with you again, but for his next task you find that a journeyman's understanding of Herbalism would be helpful.  If you don't know it though, he'll still find a use for you.", objectives = "Bring 20 Un'Goro Soil samples to Ghede on the Elder Rise of Thunder Bluff.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3762] = { id = 3762, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assisting Arch Druid Runetotem", description = "Excuse me {class}, but I'd like just a moment of your time if possible.\n\nThe Cenarion Circle in Thunder Bluff is most interested in seasoned adventurers such as yourself to lend them aid in a vital research project.  While I do not know the specifics, I can inform you that none other than Hamuul Runetotem is spearheading this research.\n\nPlease - if you are interested, speak with him directly on the Elder Rise within Thunder Bluff proper.", completion = "Greetings, {class}; I am glad you are interested in assisting our research. There is much to do, and I would be doing you a disservice if I informed you that the work this entails is not dangerous. Hopefully this will not scare you off... but from the looks of you, I take it that danger is something that you have dealt with before.", objectives = "Speak with Arch Druid Hamuul Runetotem in Thunder Bluff.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3763] = { id = 3763, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assisting Arch Druid Staghelm", description = "Excuse me {class}, but I'd like just a moment of your time if possible.\n\nThe Cenarion Circle in Darnassus is looking for seasoned adventurers such as yourself to lend them aid in a vital research project.  While I do not know the specifics, I can inform you that none other than Arch Druid Fandral Staghelm is spearheading this research.\n\nPlease - if you are interested, speak with him directly in the Cenarion Enclave within Darnassus proper.", completion = "Well now, {class}... since you were informed that I was leading this research myself, you obviously came as quickly as you could.\n\nNow that you are here, be sure to pay attention the first time I tell you the details; I have no desire to repeat myself.", objectives = "Speak with Arch Druid Fandral Staghelm in Darnassus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3764] = { id = 3764, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Un'Goro Soil", description = "The soil of Un'Goro Crater is reportedly enriched with potent magical qualities.  I want to know facts from falsehoods; go into the wilds of Un'Goro and acquire enough quality samples of soil for our continued study.\n\nYou may think that collection tasks are beneath you; that sort of attitude does not endear yourself to me or the Cenarion Circle.  Bring the samples to Jenal, who is no doubt wasting time outside behind this tree; just look for the piles of dirt.  He will handle the logistics - not I.", progress = "Ah yes, the dirt.  The Arch Druid wants twenty loads per adventurer, and twenty loads he shall get.  Let those who conspire against us fall to the wayside!", completion = "Unload your precious cargo here, noble {class}.  It must have been quite the burden... not unlike the burden I carry being a visionary.  Here is an honorarium for your work, as dictated by the Arch Druid himself.\n\nArch Druid Staghelm wants to speak with you again {name}, but for his next task you will be aided if you have a journeyman's understanding of Herbalism.  If you don't know it though, you will still be able to aid the Circle!", objectives = "Bring 20 Un'Goro Soil samples to Jenal at the Cenarion Enclave in Darnassus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3765] = { id = 3765, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Corruption Abroad", description = "Stormwind -- such a bustling hub of activity.\n\nI have traveled from afar to seek help. Often it is heard that brave adventurers roam these city streets.\n\nMy brother, Gershala, requires assistance in Darkshore. He resides in the seaside town of Auberdine.\n\nThe journey is a long and epic one. It is for this reason that I ask the help of a seasoned {class} such as yourself.", completion = "Ah, so my brother, Argos, sent you? I realize you must be weary from your travels. But we have much to talk about.", objectives = "Travel to Gershala Nightwhisper in Auberdine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3781] = { id = 3781, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morrowgrain Research", description = "With what we call an Evergreen Pouch, we have cultivated Tharlendris seeds in the soil from Un'Goro Crater.  These seeds blossom into an array of random, potent herbs.  One result is morrowgrain, a mysterious herb we know little about; I intend to unravel this mystery.\n\nTake this to Mathrengyl downstairs, and he will give you some seeds so you can get started.  If you run out, you will need to purchase more from him.", progress = "Peace and serenity be yours, friend.  You are here on business from the Arch Druid himself, yes?", completion = "Yes, this voucher is good for twenty packets of seeds.  If you run out, we have more that can be provided.  Unfortunately though, Tharlendris seeds are quite costly to produce in significant numbers.  This is why the Cenarion Circle asks that those who are assisting us help out by offsetting some of the cost.\n\nThose who return with morrowgrain find that the reward the Arch Druid offers far makes up for the cost.", objectives = "Take the Arch Druid's Seed Voucher to Mathrengyl Bearwalker in the Cenarion Enclave of Darnassus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3782] = { id = 3782, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morrowgrain Research", description = "With what we call an Evergreen Pouch, we have cultivated Tharlendris seeds in the soil from Un'Goro Crater.  These seeds have blossomed into an array of random, potent herbs.  One result is morrowgrain, a mysterious herb we know little about; I very much hope to unravel this mystery for the Circle.\n\nTake this voucher over to my daughter Bashana, and she will give you some seeds so you may assist us.  If you run out, you will need to purchase more from her.", progress = "Peace unto you, friend.  You are here on business from the Arch Druid himself, yes?", completion = "Yes, this voucher is good for twenty packets of seeds.  If you run out of seeds, I do have more that I am able to sell to you.\n\nUnfortunately {name}, Tharlendris seeds are quite costly to produce in significant numbers.  This is why the Cenarion Circle asks that those who are assisting us help out by offsetting some of the cost.  Those who return with morrowgrain find that the reward the Arch Druid offers far makes up for the cost.", objectives = "Take the Seed Voucher to Bashana Runetotem in Thunder Bluff.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3783] = { id = 3783, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "re We There, Yeti?", description = "My friends are always coming up with great ideas. I've never felt like I could match them... until today! I just drew up the plans for something great! If you promise not to tell, I'll let you in on the secret... \n\nI'm going to make a mechanical yeti! Not only are my friends sure to be freaked out when they see it, but when they get over that, I know they'll be impressed!\n\nI need thick yeti fur from the ice thistle yeti to start with. Will you help? You'll find them to the southeast.", progress = "I've got lots to get started on here. Please get me those furs as soon as you can!", completion = "These furs are perfect, {name}. We're off to a great start here!", objectives = "Collect 10 Thick Yeti Furs for Umi Rumplesnicker in Everlook.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3784] = { id = 3784, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assisting Arch Druid Runetotem", description = "Excuse me {class}, but I'd like just a moment of your time if possible.\n\nThe Cenarion Circle in Thunder Bluff is most interested in seasoned adventurers such as yourself to lend them aid in a vital research project.  While I do not know the specifics, I can inform you that none other than Hamuul Runetotem is spearheading this research.\n\nPlease - if you are interested, speak with him directly on the Elder Rise within Thunder Bluff proper.", completion = "Greetings, {class}; I am glad you are interested in assisting our research. There is much to do, and I would be doing you a disservice if I informed you that the work this entails is not dangerous. Hopefully this will not scare you off... but from the looks of you, I take it that danger is something that you have dealt with before.", objectives = "Speak with Arch Druid Hamuul Runetotem in Thunder Bluff.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3785] = { id = 3785, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morrowgrain Research", description = "Here's your Evergreen Pouch that you'll need to use the Tharlendis seeds with.  You also need to have Un'Goro soil samples on hand to use as fertilizer for the seeds.  Just use the pouch when you have everything; the pouch will take care of the rest.\n\nWhen you have enough morrowgrain, bring them here to me in the enclave.  Please don't bother the Arch Druid; he's a very busy man, and he doesn't need to be disturbed every time someone returns with another batch of morrowgrain!", objectives = "Use an Evergreen Pouch with a Packet of Tharlendis Seeds and two Un'Goro Soil samples to try and cultivate samples of Morrowgrain.\n\nBring 10 Morrowgrain to Mathrengyl Bearwalker in Darnassus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3786] = { id = 3786, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morrowgrain Research", description = "Here's your Evergreen Pouch that you'll need to use the Tharlendis seeds with.  You also need to have Un'Goro soil samples on hand to use as fertilizer for the seeds.  Just use the pouch when you have everything; the pouch will take care of the rest.\n\nWhen you have enough morrowgrain, bring them to me here on Elder Rise.  Please don't bother the Arch Druid; he'll be very busy with the research, as well as the multitude of concerns he has!", progress = "Yes {name}, have you grown some morrowgrain for the Arch Druid's important research?  The mysterious properties of Un'Goro Crater become clearer with each passing day, thanks to the help you are giving us.", completion = "Well done {name}, I will be sure to give these to the Arch Druid himself when he has need of them.  Meanwhile, please accept this as a token of the Cenarion Circle's appreciation.\n\nOur need for morrowgrain, for now, is constant; if you wish to continue aiding us, then please return when you have cultivated more of it.", objectives = "Use an Evergreen Pouch with a Packet of Tharlendis Seeds and two Un'Goro Soil samples to try and cultivate samples of Morrowgrain.\n\nBring 10 Morrowgrain to Bashana Runetotem in Thunder Bluff.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3787] = { id = 3787, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jonespyre's Request", description = "Excuse me, friend...\n\nA colleague of mine would like to speak with you about the research you are doing in conjunction with the Cenarion Circle.  He is a druid by the name of Quintis Jonespyre, and he resides in Feathermoon Stronghold, Feralas.  He would like to confer with you about morrowgrain... and he very much would like for you to keep our discussion from the ears of the Arch Druid.\n\nIf you're interested, speak with him; no doubt, all will be revealed once you do.", completion = "I thank you for coming, weary traveler!  Allow me to introduce myself - I am Quintis Jonespyre, druid and humble servant of Malfurion and the Cenarion Circle.  My colleagues (General Shandris Feathermoon and the Protectorate - mayhap you've heard of us) and I wanted to talk with you about the work you are doing for Fandral Staghelm in Darnassus.\n\nBefore we get much further, I'd like to ask that our discussion stay between just us.  If you have no problem with this, then we may proceed.", objectives = "Speak with Quintis Jonespyre in Feathermoon Stronghold.Excuse me, friend...\n\nA colleague of mine would like to speak with you about the research you are doing in conjunction with the Cenarion Circle. He is a druid by the name of Quintis Jonespyre, and he resides in Feathermoon Stronghold, Feralas. He would like to confer with you about morrowgrain... and he very much would like for you to keep our discussion from the ears of the Arch Druid.\n\nIf you're interested, speak with him; no doubt, all will be revealed once you do.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3788] = { id = 3788, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jonespyre's Request", description = "Excuse me, friend...\n\nA colleague of mine would like to speak with you about the research you are doing in conjunction with the Cenarion Circle.  He is a druid by the name of Quintis Jonespyre, and he resides here in Feathermoon Stronghold.  He would like to confer with you about morrowgrain... and he very much would like for you to keep our discussion from the ears of the Arch Druid.\n\nIf you're interested, speak with him; no doubt, all will be revealed once you do.", completion = "I thank you for coming, weary traveler!  Allow me to introduce myself - I am Quintis Jonespyre, druid and humble servant of Malfurion and the Cenarion Circle.  My colleagues (General Shandris Feathermoon and the Protectorate - mayhap you've heard of us) and I wanted to talk with you about the work you are doing for Fandral Staghelm in Darnassus.\n\nBefore we get much further, I'd like to ask that our discussion stay between just us.  If you have no problem with this, then we may proceed.", objectives = "Speak with Quintis Jonespyre in Feathermoon Stronghold.Excuse me, friend...\n\nA colleague of mine would like to speak with you about the research you are doing in conjunction with the Cenarion Circle. He is a druid by the name of Quintis Jonespyre, and he resides here in Feathermoon Stronghold. He would like to confer with you about morrowgrain... and he very much would like for you to keep our discussion from the ears of the Arch Druid.\n\nIf you're interested, speak with him; no doubt, all will be revealed once you do.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3789] = { id = 3789, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assisting Arch Druid Staghelm", description = "Excuse me {class}, but I'd like just a moment of your time if possible.\n\nThe Cenarion Circle in Darnassus is looking for seasoned adventurers such as yourself to lend them aid in a vital research project.  While I do not know the specifics, I can inform you that none other than Arch Druid Fandral Staghelm is spearheading this research.\n\nPlease - if you are interested, speak with him directly in the Cenarion Enclave within Darnassus proper.", completion = "Well now, {class}... since you were informed that I was leading this research myself, you obviously came as quickly as you could.\n\nNow that you are here, be sure to pay attention the first time I tell you the details; I have no desire to repeat myself.", objectives = "Speak with Arch Druid Fandral Staghelm in Darnassus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3790] = { id = 3790, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assisting Arch Druid Staghelm", description = "Excuse me {class}, but I'd like just a moment of your time if possible.\n\nThe Cenarion Circle in Darnassus is looking for seasoned adventurers such as yourself to lend them aid in a vital research project.  While I do not know the specifics, I can inform you that none other than Arch Druid Fandral Staghelm is spearheading this research.\n\nPlease - if you are interested, speak with him directly in the Cenarion Enclave within Darnassus proper.", completion = "Well now, {class}... since you were informed that I was leading this research myself, you obviously came as quickly as you could.\n\nNow that you are here, be sure to pay attention the first time I tell you the details; I have no desire to repeat myself.", objectives = "Speak with Arch Druid Fandral Staghelm in Darnassus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3791] = { id = 3791, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mystery of Morrowgrain", description = "Let me to be frank with you, {name}.  I'm interested - nay, concerned with why the Arch Druid in Darnassus is using the name of the Cenarion Circle as well as the Circle's resources to procure vast amounts of morrowgrain.  I'm a researcher - curses are my specialty.  I've heard that morrowgrain, under the right conditions, exude qualities like other herbs used in primitive curses.\n\nI want to know more, and I ask for your help.  Bring me ten morrowgrain, and I will be sure to take care of you.", progress = "I'm looking for ten morrowgrain - that should be enough to at least get my research started.  I'll no doubt burn through a lot of those going down wrong paths, but such is the nature of research.", completion = "Gah, these morrowgrain make me feel... weird.  What in the name of Elune is Staghelm up to with these things?\n\nAnyway, thank you again for your help.  Here's a little something... you know, for the effort.  My research on morrowgrain is going to take a while, and I no doubt am going to need more.  While I'm at it, I suppose I could take the time to see if morrowgrain have some pertinent alchemical uses.  Still, I feel uncomfortable even being around them.", objectives = "Bring 10 Morrowgrain to Quintis Jonespyre in Feathermoon Stronghold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3792] = { id = 3792, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morrowgrain to Feathermoon Stronghold", progress = "Hello again, {name}.  My research is progressing fairly well, but if you have five more Morrowgrain I'd be happy to take them off your hands.  Well... happy is a figurative term in this case; the more I am around them, the more uncomfortable I feel.  Still, my research demands I buckle down and get through this.", completion = "Thanks {name}; I'll just store these out of the way for the time being.  While I don't command the resources that Staghelm does, I am able to give you a little something for your trouble.  Anyway, who knows what will happen if Staghelm keeps getting Morrowgrain after Morrowgrain.  There's something fishy going on, mark my words.\n\nRemember that I'm always looking for more Morrowgrain.  I'll take them in quantities of five at a time." }
quests[3801] = { id = 3801, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Iron Legacy", description = "Greetings, {name}. I am Franclorn Forgewright. Yes, the Franclorn Forgewright responsible for the stonewrought method of architecture. You have undoubtedly passed through or stood upon one of my creations in your adventures across our war torn world.\n\nYou are probably wondering why I am here and what it is that I want from you - both valid questions.\n\nI need your assistance, of course. In exchange for your assistance, I shall grant you the key to the depths of my accursed city.", sourceObjective = "Speak with Franclorn Forgewright at Forgewright's Tomb in Blackrock Mountain if you are interested in obtaining a key to the city major.", completion = "Whether it is greed which brought you here or an act of selfless devotion, what you are about to undertake is for the good of us all.", sourceObjectiveStatus = "unverified-source-field" }
quests[3802] = { id = 3802, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Iron Legacy", description = "You will find Fineous Darkvire beyond the Ring of Law, in the Hall of Crafting. Kill the miserable cur and recover Ironfel.\n\nTake Ironfel to the Shrine of Thaurissan and place the hammer in its rightful place: In the hands of the statue erected in my honor.\n\nWhen this is done, the compartment in which I stored the master key will open. More importantly, Ironfel will remain forever in my grasp. Should they make an attempt to remove the hammer; both the statue and hammer will shatter, lost forever.", progress = "The statue looms ominously above you.", completion = "The hammer slides firmly into place, within the grasp of the massive Dark Iron monument. A tiny compartment opens at the base of the statue. Inside you find...", objectives = "Slay Fineous Darkvire and recover the great hammer, Ironfel. Take Ironfel to the Shrine of Thaurissan and place it on the statue of Franclorn Forgewright.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3803] = { id = 3803, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morrowgrain to Darnassus" }
quests[3804] = { id = 3804, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morrowgrain to Thunder Bluff", progress = "The Arch Druid is always looking for more morrowgrain for the Cenarion Circle's research project on Un'Goro Crater.  We take them in increments of ten, and award you with a cache of goods you should find useful.  When you have ten, let me know and I will award you accordingly.", completion = "Excellent - this morrowgrain will no doubt help when the time comes.  We know that the night elves are conducting similar research into these herbs, though it isn't clear to what end they will use them for if they discover anything.  The Arch Druid thinks that the need for morrowgrain will remain until we've figured out the mysteries behind this herb.\n\nThis is for you, {name}.  The Cenarion Circle thanks you for your continued support." }
quests[3821] = { id = 3821, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dreadmaul Rock", description = "Sha'ni was sent to investigate reports of strange ritualistic activity coming from the Firegut ogres of the Burning Steppes over three weeks ago.\n\nGoretooth tells me that he hasn't heard from anyone in that platoon and that it's best that I move on and focus on the task at hand. Can you believe it? That's my wife!\n\nI can't leave my post, {name}, but I must know what became of Sha'ni. Travel to the Burning Steppes and search for her.", sourceObjective = "Venture forth to the Burning Steppes and find out what became of Sha'ni Proudtusk.", completion = "My poor Thal'trak.\n\nWe were planning on moving in with my mother and father in the Hinterlands after our tours were over. Now those plans are ruined!", sourceObjectiveStatus = "unverified-source-field" }
quests[3822] = { id = 3822, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krom'Grul", description = "My whole platoon was captured, {name}. All were slain - except me.\n\nTheir leader, Krom'Grul, wanted to save me for some sort of ritual.\n\nI was chained to this altar and brutalized by the beast. My physical being ceased functioning after an hour of this torture. The beast then ripped my wedding nose-ring off of my face and stuck it on his finger. I had never seen such savagery!\n\nFind Krom'Grul and kill him! Take my ring back to Thal'trak.\n\nAnd {name}, tell him that we will meet again... in another life.", progress = "Did you find Sha'ni? Is she ok?", completion = "<Thal'trak collapses.>\n\nWe were going to move to the Hinterlands. Did she tell you? This was going to be her last mission.\n\n<Thal'trak sobs.>\n\nI don't want it, {name}. Keep it, throw it away, I don't care! The ring means nothing to me now. Not without her...", objectives = "Recover Sha'ni's Nose-Ring from Krom'Grul and return it to Thal'trak in Kargath. Search the various caves and mines in Dreadmaul Rock.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3823] = { id = 3823, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Extinguish the Firegut", description = "We must strike at our enemies before they strike at us!\n\nI'll make this brief, soldier.\n\nThe Firegut ogres of the Burning Steppes are allies of the Blackrock orcs. They work closely with those vile orcs, keeping the mineral rich Dreadmaul Rock guarded and the supply lines open at all times.\n\nLeave your mark, {name}. Cripple their forces and return to me when the job is done.\n\n<Oralius grabs at the air and makes a choking motion.>\n\nI WILL KILL YOU, WINKY!", completion = "Outstanding, soldier! The orcs and ogres will be reeling from this blow for minutes, maybe even hours!", objectives = "Slay 15 Firegut Ogre-Mages, 7 Firegut Ogres, and 7 Firegut Ogre Brutes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3824] = { id = 3824, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gor'tesh the Brute Lord", description = "They're reeling I tell you! Our next strike must be decisive.\n\nThe brute lord, Gor'tesh, must be slain. More importantly, his head must be returned to me so that I may prepare the third phase of our attack on the Firegut ogres.\n\nBe warned, soldier, Gor'tesh rules not from Dreadmaul Rock but from a Blackrock orc structure to the west of Dreadmaul Rock.\n\nYour orders, then, are simple. Find Gor'tesh and chop off his fat head. Return to me when the job is done.\n\nSHUT UP, WINKY!", progress = "Oh glorious day! Have you returned with the head?", completion = "Just look at it, soldier. Disgusting! When the remaining Firegut ogres see this fat mug stuck on a pike sitting at the top of their mountain, mass hysteria will ensue!\n\n<Oralius cackles wildly.>", objectives = "Collect Gor'tesh's Lopped Off Head.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3825] = { id = 3825, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogre Head On A Stick = Party", description = "Just one last thing you must do, soldier.\n\nI've taken the liberty of putting Gor'tesh's head on a pike. Now all you have to do is take this head to the top of Dreadmaul Rock and stick it into the ground. Once you do that, watch as those cowardly ogres run for their lives! After you've had your fun, come back to me and I'll reward you for all of your hard work.\n\n<Oralius seems to be losing touch with reality.>", completion = "Outstanding work, soldier! Simply amazing! Oh I'll get the medal of bravery for this, er, I mean you'll be rewarded handsomely for this!", objectives = "Take Gor'tesh's Lopped Off Head and place it at the top of Dreadmaul Rock. Look for a soft dirt mound to plant the pike.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3841] = { id = 3841, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Orphan Looking For a Home", description = "Oh, hello, {name}. I'm so glad to see you again. How was your trip to Darnassus?\n\nWell, you'll be happy to know that we've made quite a bit of progress while you've been gone. We even saved a nest full of eggs. Unfortunately, the mother died before we got to her.\n\nSay, would you want one for a pet? They look to hatch soon, so they'll need a good <father/mother>. What do you say?\n\nIf you're really interested, take one of the eggs to Quentin at the race tracks in Shimmering Flats. He'll tell you more.", progress = "Why hello, {class}.\n\nDon't let my location fool you, I'm really not here for the races... as entertaining as they may be.\n\nI'm actually here in Thousand Needles investigating all I can to find out how salvageable the land is. It has become my crusade of sorts to revitalize and replenish the area with new, fertile soil. Perhaps I'll find there's a water source nearby.\n\nTell me you haven't noticed how odd the transition between Feralas and Thousand Needles is. Strange magic was afoot when that happened.", completion = "Ah, a sprite darter egg, and one near maturation, if I'm not mistaken. Remarkable you've found one, let alone in this good a condition. They're rarely seen in Feralas these days. I understand there were various poachers in the area trying to capture and kill them for many reasons. Too bad really... such beautiful creatures when they reach adulthood.\n\nHow did you come across such a find?", objectives = "Speak to Quentin in Thousand Needles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3842] = { id = 3842, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Short Incubation", description = "The Moonweavers, huh? Most intriguing. I wish the sprite darters could truly appreciate what it means to have those two look after them. They are both quite capable.\n\nSo, they gave you the egg as a gift. Well, then you should be responsible for it for as long as you desire. It appears it's almost ready to hatch, but we should ensure it's healthy and no damage has been done to it.\n\nI only need two elixirs of fortitude for a small spell to protect the egg. I have the rest of the components here with me.", progress = "The longer I stay here, the more tempted I am to partake in these races, {name}. Truly boggling...\n\nHave you found the elixirs yet? Once I can tell if the egg is going to be healthy or not, I'll return it to you to hold onto until it's prepared to hatch.\n\nLet me know.", completion = "Wonderful. These will do nicely. Give me a moment to mix together my components and we shall see how well this egg is going to do.", objectives = "Bring 2 Elixir of Fortitudes to Quentin in Thousand Needles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3843] = { id = 3843, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Newest Member of the Family", description = "A magnificent specimen, {name}. If this creature survives gestation, then it'll be a healthy pet indeed!\n\nThere is one last thing I would suggest doing if you plan on following through with this--head to Aerie Peak in the Hinterlands. Speak to a dwarf there named Agnar Beastamer, he's a master animal handler and should be able to guide you in the final steps of incubation.\n\nBut hurry, {name}, this egg is fragile and will not last long without proper care.", progress = "Greetin's, {name}. How can I be of service to ya?", completion = "Well, well, well... I haven't seen one of these in a dragon's age. Faerie dragon, if I'm not mistaken... looks to be of the sprite darter variety. Excellent, excellent indeed.\n\nWell, if this little fella's gonna hatch and live to be strong and healthy, then we should get some food for it. Good ya got it to me in time.", objectives = "Take your Fragile Sprite Darter Egg to the Hinterlands and speak to Agnar Beastamer, but hurry, you only have 1 hour to find him before the hatchling within the egg dies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3844] = { id = 3844, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's a Secret to Everybody", description = "A destroyed raft rests along the shoreline. Considering this is only a small pond, it is not clear as to how it ended up here, although looking at the trees tells you that the water level may not be constant.\n\nPerhaps a little exploration in the area might uncover more clues...", sourceObjective = "Look around in the pond for a clue about who this wrecked raft may belong to.", completion = "A water-logged pack rests at the bottom of the pond.", sourceObjectiveStatus = "unverified-source-field" }
quests[3845] = { id = 3845, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's a Secret to Everybody", description = "Grabbing onto it, you pull the pack back to the shore. Perhaps if you examine the items inside the pack, you might find out more about who it belongs to.\n\nThere are a few stray travelers at Marshal's Refuge. Perhaps you might find out more there.", progress = "Hi there. I've seen you before... Haven't I?", completion = "Oh... Yes, these things do look familiar... well, kind of...", objectives = "Examine the items inside the pack and bring them to their owner.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3861] = { id = 3861, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "CLUCK!", description = "\"Cluck... cluck... cluck... BACAW!\n\nCluck... cluck... cluck.\"\n\nThe chicken looks up at you and then starts to scratch its claws into the ground. You think it is spelling out a word, but you are not sure what it is. Could it be... S-A-L-D-E-A-N? Before you can ask, the chicken turns away and goes about its business.", progress = "The chicken stares at you with dark, cold eyes. It waits for you hungrily.\n\n\"BACAAAW!\n\nCluck...cluck...cluck.\"", completion = "\"BACAW!!!\"\n\nThe chicken starts to gobble up the feed you put down.\n\nAfter a moment, the chicken looks around, startled. It uncomfortably shuffles back and forth. Is this chicken pregnant? You think you better check underneath it.", objectives = "Find some Special Chicken Feed and return to your befriended chicken. When you find it, /cheer at it before trying to give it the Special Chicken Feed.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3881] = { id = 3881, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Expedition Salvation", description = "I don't know how you made it here, but you're a sight for sore eyes!  I'm Williden Marshal, and I lead a non-aligned expedition troupe.  Our latest and greatest endeavor has met with what seems like countless disasters, the most serious of which being that we underestimated the savagery of Un'Goro Crater!\n\nAs we fled our base camps in the southwestern and northeastern parts of the crater, we left behind vital supplies.  You look like you're capable enough - can you help us by getting them back?", progress = "If we're going to have any chance of getting out of here alive, we'll need our big crate of foodstuffs.  Also, getting at least some of our research equipment back would be a blessing in a sea of misery.", completion = "You got both our foodstuff AND our research equipment back!  You've not only saved the expedition, you've also saved our lives.  I and the rest of my team can't thank you enough; we just might make it here for a while now thanks to you.\n\nWhile we don't have much, I'm certainly not going to leave you high and dry for the invaluable help you've given us.  Thank you, {name} - you've got a friend in Marshal Expeditions!", objectives = "Bring a Crate of Foodstuffs and Research Equipment to Williden Marshal in Un'Goro Crater.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3882] = { id = 3882, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Roll the Bones", description = "You'd think that being chief digger for Marshal Expeditions means I like digging.  There might be worse things to do in this world... but none really leap to mind.\n\nWe were supposed to be digging in Terror Run - FANTASTIC name by the way - for dead stegodons and diemetradons.  Well, there are plenty of live ones there too!  Wil and Hol are still all about studying this death trap, so we need those dinosaur bones.  Between you and me though, bringing some from live ones will work out just as well.", progress = "Think whatever you want of me, but they're not going to care if the bones they get to research are from ones from ancient stegodons and diemetradons or the ones that almost devoured us wholesale when we were trying to set up our camps.  I'll just be happy if we get out of here alive...", completion = "Excellent, these should do the trick.  And now, if you'll permit me...\n\nTHANKS FOR DIGGING ALL OF THESE BONES OUT OF THE GROUND FOR US AND NOT HURTING THE NATIVE BEASTS IN ANY WAY.\n\nWhether you really did or didn't, I don't want to know.  Let's keep it that way, shall we?  Here - maybe this will keep your lips shut on the whole thing.  Anything to get out of here alive, I say!", objectives = "Bring 8 Dinosaur Bones to Spark Nilminer in Un'Goro Crater.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3883] = { id = 3883, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alien Ecology", description = "Just because we've suffered a setback doesn't mean that research must stop!  We were investigating the Gorishi insects in the southern part of the crater before winding up here.  Their presence is alien to the ecology of Un'Goro, and we want to find out why.\n\nIn their hive network must be larval hatcheries.  You can identify these places by their hanging larval spawns.  Use this vial to take a sample of the hive wall near any of the hatcheries.  Bring it back to me for study, but be careful!", progress = "Do you have the sample of the Gorishi hive for me to study, {name}?", completion = "Yes, this will do nicely.  You've been a great help... I wish I could give you more than this, but being virtually stranded in the middle of a savage land does limit what I can and cannot give.  Rest assured though - the research done here would not have been possible without your assistance!", objectives = "Use the Scraping Vial to collect a Hive Wall Sample from one of the Gorishi hive hatcheries in Un'Goro Crater. Look for the chambers with the hanging larval spawns.\n\nBring the Hive Wall Sample to Hol'anyee Marshal in Un'Goro Crater.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3884] = { id = 3884, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Williden's Journal", description = "You have uncovered a mangled journal.  Parts of it remain legible, with a Williden Marshal claiming ownership over the contents therein.  If the journal is accurate, then Williden may be found somewhere in the northern part of the Crater; according to the journal, he and his companions sought higher ground from the savage beasts of the Crater once their base camps were overrun.", progress = "Hello there!  I and my companions are happy to see some living beings here other than overgrown savage beasts!  What brings you into the Un'Goro Crater?", completion = "Well look at this - my journal!  I thought it was lost, much like almost everything else we brought into Un'Goro.  I thank you kindly for returning this to me!", objectives = "Return the journal to Williden Marshal somewhere in Un'Goro Crater.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3901] = { id = 3901, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rattling the Rattlecages", description = "You've shown your potential to the Forsaken under normal circumstances {name} - now let's see you under pressure.\n\nThe Rattlecage skeletons, more mindless minions of menace, are a tougher foe than the zombies you have faced thus far.  Again, thin their numbers and prove yourself to the Forsaken.  Do not tarry - when you are done, speak to me again.", completion = "I am finished with you, {name} - you have shown yourself to be worthy of the freedom that you have been given.  Many will stand against you for what you have become, but know that no matter what they may try to do against us, we are free and will not be shackled again.\n\nTake these and be on your way.  You have much to accomplish, {class}.", objectives = "Kill 8 Rattlecage Skeletons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[3902] = { id = 3902, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scavenging Deathknell", description = "You there!  If you're looking for something to make yourself useful, then listen up!\n\nWe need fresh out-of-the-ground recruits to head into Deathknell and search for any sort of useful equipment.  Most likely, they'll be in stacks of boxes.  We expect more recruits to be rising soon, and unless we want them to stumble about naked we had better get to scavenging!\n\nWell get to work, you miserable bag of bones!  I'm not going to reward those without some hustle.", progress = "Have you managed to scavenge up some useful items for us?  There is no shame in reusing that which has been tossed aside.  No one is going to give us any handouts - we Forsaken will fend for ourselves!", completion = "Great work {name}, I knew you weren't useless.  Here - have one of the better items I've found out of the lots that have been collected so far.", objectives = "Search Deathknell and the vicinity for 6 pieces of Scavenged Goods, and return them to Deathguard Saltain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
